INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd6-zhelaniya-rebenka-ostalis-na-potom',
  'Желания ребёнка остались на потом',
  (SELECT id FROM "Authors" WHERE name = 'Ласло Константинов' ORDER BY id LIMIT 1),
  'mrd6/mrd6-zhelaniya-rebenka-ostalis-na-potom.jpg',
  'data:image/jpeg;base64,',
  1222,
  895,
  'Ещё перед тем, как начали бить куранты, вдруг забилось сердечко маленького Славы. Окна в их тёплой трёшке на девятом этаже слегка затрещали: во дворе начался салют. Люди на улице не стали дожидаться окончания телевизионн',
  '[{"kind":"image","path":"mrd6/mrd6-zhelaniya-rebenka-ostalis-na-potom.jpg","caption":null},{"kind":"paragraph","text":"Ещё перед тем, как начали бить куранты, вдруг забилось сердечко маленького Славы. Окна в их тёплой трёшке на девятом этаже слегка затрещали: во дворе начался салют. Люди на улице не стали дожидаться окончания телевизионного поздравления, а приняли решение отметить праздник прямо сейчас — почему бы и нет? Что такое «принять решение», Слава пока не знал — ему всего четыре."},{"kind":"paragraph","text":"Огни сверкали. То было не похоже ни на что другое в жизни ребёнка — и он загорелся желанием всё это как следует разглядеть."},{"kind":"paragraph","text":"— Интересно, ой как интересно, — пищал Славка, сидя за общим столом, но никто не слышал."},{"kind":"paragraph","text":"Его окружали родственники, но мальчик, кроме мамы и папы, никого не помнил, хотя всем его детская мордашка знакома. Рядом друзья, не его, а опять же родительские. Все эти люди сейчас заняты тем, что передают друг другу шариковую ручку. Нужно написать на бумажке идеально сформулированное желание, а потом запить пепел доброй порцией игристого ровно в двенадцать."},{"kind":"paragraph","text":"Все эти тёти и дяди выше Славы, он в доме сегодня единственный ребёнок. Празднично накрытый стол по центру кухни, шумный телевизор на стене под потолком. Слава сидел там же, но все смотрели на телевизор."},{"kind":"paragraph","text":"А ему неймётся — ёрзает. И чем больше взрывов звучит на улице, тем сильнее сжимаются в нетерпении его кулачки, тем чаще его жопка выдаёт вензеля на стуле в детском нетерпении."},{"kind":"paragraph","text":"Он ещё раз бросил жалобный взгляд на маму, и та наконец обратила на ребёнка внимание. Пьяная она, но легко связала шум за окном и горящие глаза сына. Наклонившись к его светлой головушке, тихо произнесла:"},{"kind":"paragraph","text":"— Давай. Беги, только тихо."},{"kind":"paragraph","text":"Слава в ту же секунду рванул что есть мочи, и в общей человеческой трескотне не услышал, как позади рухнул табурет, и отец что-то прокричал."},{"kind":"paragraph","text":"По скользкому линолеуму, по пушистому тёплому ковру он добежал до родительской спальни, где раздвинул шторы и запрыгнул на подоконник. Его зрачки, расширенные из-за недостатка света в комнате, впитывали в себя каждую искорку божественного праздника за стеклом."},{"kind":"paragraph","text":"Что значит «божественный», он тоже ещё не понимал."},{"kind":"paragraph","text":"Огни отражались в чёрных глазках, детская улыбка, умиляющая любого родителя, уже секунд десять не спадала. На синем снегу во дворе чёрные точки запускали огненные ракеты. Точек множество, они разбрелись по углам детской площадки: вот летит один снаряд, второй через мгновение у турника, а после третий догоняет их в воздухе — и начинается яркая, ни на что не похожая разноцветная феерия."},{"kind":"paragraph","text":"Мальчик не знал, почему фейерверк и яркие ледовые городки для него куда важнее на Новый год, чем подарки или конфеты. А о Дедушке Морозе он и совсем не думал. Не потому, что в него не верил, просто ещё пару праздников назад седой бородач заставил одетого в дурацкие чулки Славу рассказывать на табуретке какой-то стишок, да ещё перед кучей детей. Стих он сейчас не вспомнит, но смех отца и этих засерь из группы «Динозаврик» блокировал в его сознании тождество Нового года и Деда Мороза."},{"kind":"paragraph","text":"Сидя на подоконнике, Слава опёрся ладошками на стекло пластикового окна, которое никогда не замерзало настолько, чтобы можно было увидеть древовидные узоры — один из атрибутов праздника в памяти его родителей. Смотрел он вниз, на парковку, потом услышал чей-то крик:"},{"kind":"paragraph","text":"— Сейчас вы все охереете, что я купил!"},{"kind":"paragraph","text":"Что такое «охереть», Слава только догадывался."},{"kind":"paragraph","text":"И ждал он великого суперпраздника, такого, что в деревне у бабушки все петухи услышат. Так про петухов всегда изъясняется его мама, когда папа начинает говорить на повышенных тонах. Однако исступление Славки было прервано: всё вмиг пропало, а в окне вместо двора показалась детская испуганная гримаса. Отец включил в комнате свет."},{"kind":"paragraph","text":"— Ты куда, блядь, залез, пацан? Я кому кричу там, кричу?"},{"kind":"paragraph","text":"Он сдёрнул сына с подоконника и потряс в воздухе."},{"kind":"paragraph","text":"— Зову тебя, а он пошёл, побежал, деловой. Чё, от меня прячешься, хм?"},{"kind":"paragraph","text":"От отца пахло рыбой и водкой — оно всегда так, но в тот раз как-то по-особенному: слишком пьяно, невыносимо жирно."},{"kind":"paragraph","text":"— Чё молчишь? Дать те по башке, чтоб слушал?"},{"kind":"paragraph","text":"Слава молчал: просто не знал, как говорить с тем, кто его как куклу трясёт. Мальчик висел, дёргаясь в отцовских руках, — тут уж о фейерверках и думать забудешь."},{"kind":"paragraph","text":"— Я спрашиваю, ты чё молчишь — язык проглотил или боишься, а? Боишься меня?"},{"kind":"paragraph","text":"Ребёнок моргал, не понимая, что ответить. У него болели плечи, и только когда к глазам стали подходить горячие слёзы, отец его отпустил."},{"kind":"paragraph","text":"— В кого ты такой дебил растёшь? Смотреть противно. Дуй отсюда, говорю, и имей уважение к гостям — позоришь меня!"},{"kind":"paragraph","text":"Всё бы ничего, но мужчина вдогонку дал ребёнку оплеуху. Когда тот побежал прочь на своих маленьких ножках, отец задёрнул шторы, выключил свет и поплёлся, пошатываясь. По пути на кухню зашёл в туалетную комнату и, опёршись на стену плечом, стал громко ссать."},{"kind":"paragraph","text":"Слава прибежал к столу молча — не плакал ни секунды, — сел на стул, взял мандаринку и принялся очищать плод от кожуры. По телевизору что-то пели, Славка не слушал: он сейчас совсем отрешился. Его мама, накручивая указательным пальцем прядь покрытых лаком волос, шушукалась с мужчиной. Она слышала, что муж в туалете, и заискивающая женская улыбка не сходила с её лица."},{"kind":"paragraph","text":"А на Славку, еле фокусируя взгляд, смотрела незнакомая тётя с изрядно красными щеками. Она с удивлением произнесла:"},{"kind":"paragraph","text":"— Тань, глянь-ка на ребёнка."},{"kind":"paragraph","text":"— Чего?"},{"kind":"paragraph","text":"Мать обернулась и ахнула:"},{"kind":"paragraph","text":"— Ты где так весь растормошился? А, засранец наш? Иди ко мне, причешу. Щас президент будет поздравлять, давай-ка, усаживайся ко мне, я поухаживаю за сыном, правда ведь — сын ты или не сын?"},{"kind":"paragraph","text":"— Сын он тебе, — вторила тётя с улыбкой."},{"kind":"paragraph","text":"Программа поздравления началась."},{"kind":"paragraph","text":"— О, вовремя! — сказал отец, входящий в кухню. — Наливайте."},{"kind":"paragraph","text":"— Артём, всё уже налито. Никто желание своё не потерял?"},{"kind":"paragraph","text":"— Блин. Я потерял."},{"kind":"paragraph","text":"— Да вот оно, перед носом! Всё! Тихо. Готовьтесь."},{"kind":"paragraph","text":"Когда начали показывать Кремль, все в кухне затихли. Слава хотел было схватить со стола дольку мандаринки, но мама, расчёсывая его светлые волосы, одёрнула:"},{"kind":"paragraph","text":"— Имей уважение."},{"kind":"paragraph","text":"Слава смиренно сидел на коленях матери, стараясь показать то самое уважение к окружающим и к мужчине в телевизоре. Ему не было понятно, о чём тот говорит и почему на него накричал в спальне папа. Слава смотрел на свои шерстяные носочки и ждал, когда взрослые снова начнут громко разговаривать."},{"kind":"paragraph","text":"Когда пепел желаний все, кроме Славы, запили алкоголем, громкие разговоры продолжились. Новый год наконец постучался в двери — правда, не Славкиного дома, каких-то других домов. Слава его не чувствовал."},{"kind":"paragraph","text":"Вот пропал Новый год. Всё пропало."},{"kind":"paragraph","text":"Ребёнка отправили мыть руки и одеваться."},{"kind":"paragraph","text":"— Сына, иди носки переодень, пжлст, и штаны те возьми, которые мы с тобой, это самое… в садик одеваем, хорошо? На улицу пойдём, — дожёвывая что-то, сказала мама."},{"kind":"paragraph","text":"— Ладно, — ответил Слава и сполз с материнских колен."},{"kind":"paragraph","text":"Все решили выпить ещё раз, «на посошок», а батьке, видимо, уже хватило, когда ещё пепел желания запивал: как только рюмки взлетели в воздух, он потерял равновесие и неуклюже рухнул на ребёнка."},{"kind":"paragraph","text":"— АРТЁМ! АЛКАШИНА! ТЫ РЕБЁНКА УГРОБИШЬ!!"},{"kind":"paragraph","text":"— ХОРОШО, ВСЁ, ХОРОШО, Я РЯДОМ С НИМ УПАЛ, НЕ МОРОСИ, — он перевернулся с задницы и посадил на попу испуганного ребёнка. — СЛАВ, — пару пощёчин, не нужных вовсе. — СЛАВ! НЕ УШИБСЯ?"},{"kind":"paragraph","text":"Вокруг тельца собрались абсолютно все в этом доме — загремели маты, закричали женщины. Песен из телевизора было не слышно: кто-то, видимо, убавил звук. Слава открыл глаза и увидел над собой море красных лиц. Среди них он узнал только маму: та держала его головку и смотрела прямо в глаза."},{"kind":"paragraph","text":"— Спасибо тебе, Господи! Он дышит, — сказала она. — Артём, я с тобой разведусь, нахрен! Доведёшь ты меня, свинья неуклюжая!"},{"kind":"paragraph","text":"— А чё я, чё он под ногами, чего это я?"},{"kind":"paragraph","text":"Задав все эти вопросы с выпученными глазами и получив только один ответ: «Ничё!», отец поднялся, обошёл людей. Надув обиженно губки, он налил себе в рюмку водки, молча выпил и ушёл на балкон курить, даже не оборачиваясь. Хрустя коленями, встали остальные мужчины. Они присоединились к отцу."},{"kind":"paragraph","text":"И вот на кухне остались только тётки да Славка, который чувствовал себя вполне хорошо: ничего не сломал, только задница отца больно надавила на пузико — оно как-то странно ощущалось теперь."},{"kind":"paragraph","text":"Мальчик на стуле, со всех сторон на корточках сидели женщины, гладили его головушку и шептались."},{"kind":"paragraph","text":"— Таня, шли его к чёрту, подруга, подумай, он тебе ребёнка угробит."},{"kind":"paragraph","text":"— А она права, я те серьёзно. Это разве норма? Да не норма это них… ни фига! Он что сейчас сделал, посмотри."},{"kind":"paragraph","text":"— Ушёл курить."},{"kind":"paragraph","text":"— Сбежал."},{"kind":"paragraph","text":"— Сбежал!"},{"kind":"paragraph","text":"— Такие всегда сбегут — никакой надёжности…"},{"kind":"paragraph","text":"— Девки, хватит! — прервала их мать Славы, потом выдохнула. — А куда я пойду, вот куда?"},{"kind":"paragraph","text":"— Мужик найдётся, тебе проще ребёнка самой поднять, у меня такое было, представляешь…"},{"kind":"paragraph","text":"Ну и всё в таком духе. Славка это слушал, но не понимал особо, все ему задавали вопросы, где болит. А болит ли, он не мог сказать наверняка."},{"kind":"paragraph","text":"Вроде всё хорошо. Вроде обошлось."},{"kind":"paragraph","text":"— Славка, а, пацан! Ну-ка, пустите меня к сыну, — в женский круг вклинился пьяный отец. — Чё, у тебя всё нормально?"},{"kind":"paragraph","text":"Слава кивнул."},{"kind":"paragraph","text":"— Ты меня извини, не рассчитал — кто ж знал, что ты там внизу шаришься, тебя ж не видно, не слышно весь день, а тут вот как вышло, я не со зла. Да? Вот держи конфету."},{"kind":"paragraph","text":"Мальчик робко взял подарок."},{"kind":"paragraph","text":"— Ну вот, решили. Ну чё, пацан, хочешь с мужиками в город? — Он обратился к остальным: — Айда на горки… Ну чё за мины — всякое бывает. Погнали, ё-моё. Развеемся. Праздник ж."},{"kind":"paragraph","text":"— Ты ребёнка мне сейчас чуть не убил, какие горки, иди спать!"},{"kind":"paragraph","text":"— Не твоего, а нашего. Это и мой ребёнок тоже, и я решу: горки ему или не горки. Чё, согласен? Пойдём веселиться?"},{"kind":"paragraph","text":"Слава снова кивнул, а конфета, подаренная отцом, так и осталась нераскрытой лежать в тёплых детских ручонках."},{"kind":"paragraph","text":"Следующие десять минут для Славы были очень долгими. Его самым первым одели: увязали всеми мыслимыми и немыслимыми шарфами, напялили в миллион тысяч миллиардов слоёв одежды, пропихнули под курткой варежки на резинке, а на голову водрузили невозможных размеров шапку. Славка стоял в коридоре у двери один, пока все остальные искали кошельки, закуску, сигареты. Стоял, со стороны куда больше в ширину, нежели в длину. Славка — не Славка, а Смешарик."},{"kind":"paragraph","text":"Вскоре он уже был под ночным снежным небом, держа за руку маму, которая шагала так быстро, что Славка почти летел над холодным асфальтом. Ему не больно ручке: она натягивается, это да, но на нём столько надето, что совершенно не чувствуется."},{"kind":"paragraph","text":"Его папка, полураскрытый, осоловевший, топал во главе толпы, что растянулась на половину квартала. И издалека Славе его не видно. Они сейчас не вместе. Просто в одно и то же время вышли из точки А в точку Б. И если бы не большущая плотная шапка, Слава бы слышал, как недовольная мама материлась на мужа:"},{"kind":"paragraph","text":"— Торопится как, гляньте. Идиотина…"},{"kind":"paragraph","text":"Подружки её обогнали — все идут впереди, позади только она и маленький Слава. Её это бесит. Она слышит смех, видит спонтанную игру в снежки, реверансы случайным прохожим, громкие поздравления с праздником тех, кто сейчас на балконах — всё проходит мимо неё, всё веселье. Что за несправедливость! Одиночество ударило очень больно, и она сильнее сжала ручку Славки, быстрее поскакала по тротуару, догоняя уже, кажется, бывших подружек."},{"kind":"paragraph","text":"Повсюду гремели салюты, но Слава не мог оценить всю эту прелесть: он просто нёсся над землёй неведомо куда, ведомый матерью. Ребёнок как сумочка, ребёнок как багаж."},{"kind":"paragraph","text":"Спустя несколько дворов и парковок они вышли к городскому парку. В центре стояла двадцатипятиметровая ёлка — из железа и бездушия, муниципальная. Рядом залили четыре ледовые горки, самая высокая из которых почти пять метров, а её спуск достигал рекордных для города семидесяти. Такого изобилия ещё никогда не было в жизни Славки, он видел этот спуск и слепящие огни гирлянд, рассеивающие ночную тьму городка, тысячи людей вокруг и… просто не мог поверить своим глазам. Это сон, прекрасный сон, детская сказка! И всё, что было до этой секунды, вмиг забывается, и только одна мысль Славу волнует: изучать эту волшебную страну, каждый её закуток, изучать до изнеможения. Добравшись до горки, мама опустилась на колено, поправила ему шарф и показала рукой на одну из горок:"},{"kind":"paragraph","text":"— Смотри, там наверху папа. Хочешь к нему?"},{"kind":"paragraph","text":"Среди десятка людей на вершине деревянной конструкции Слава увидел человека, поднявшего руки. Тот что-то прокричал и с разбега рванул вниз по спуску. Он катился на ногах, неуклюже балансируя. Пролетая мимо Славы, отец потерял равновесие, рухнул на задницу и вылетел с ледового покрытия в снежный сугроб."},{"kind":"paragraph","text":"— Не волнуйся, ему не больно, — сказала мама, равнодушно отворачиваясь от мужчины, которого когда-то выбрала себе в мужья. — Пойдём лучше ледянку спросим."},{"kind":"paragraph","text":"Она отметила, что из колонок бьёт «что-то-из-детства-новогоднее-где-я-это-слышал» музыка. Неподалёку в тени стояли машины полицейских и медиков. Стражи правопорядка и врачеватели, сменяя друг друга, выходили из авто и курили компашками, оглядываясь и выпивая что-то из бумажных пакетиков."},{"kind":"paragraph","text":"Среди них был примечателен один человек, которого она, к сожалению, не рассмотрела и, следовательно, не запомнила. С седой головой, чисто выбритыми щеками и подбородком, чёрными, как графит, глазами. На нём был синий шарф, причудливо завязанный на шее."},{"kind":"paragraph","text":"Сей мужчина знал, что Слава придёт, но ожидал его куда раньше. Когда отец ребёнка, громко матерясь, скатился с горки в первый раз, незнакомец вышел из палатки, отапливаемой печкой-буржуйкой. С тех пор он стоял, попивая горячий чай, и не спускал глаз с новоприбывших в его ледяное царство."},{"kind":"paragraph","text":"Он — проектировщик, местный художник, что выиграл грант на создание главной праздничной локации столицы региона в этом году. Придумал дизайн ледового городка, нарисовал схему расположения горок и населил парк волшебными созданиями изо льда. О нём мало кто слышал, ещё меньше людей видели его лицо. А вот творчество было знакомо каждому здесь, хоть мало кто отдавал себе в этом отчёт. От рекламных баннеров до галерейных картин, от театральных постановок до — на удивление — звучных стихов, на которые накладывали музыку местные уличные артисты, срывая дневной куш."},{"kind":"paragraph","text":"Каждый его проект приносит небольшое состояние — всегда успех, — однако эти блага достаются тем, кто от имени художника выступает. Сам автор наблюдает со стороны — не гордясь, не улыбаясь. Отправленная им заявка на создание ледового городка была одобрена лично мэром, все действия на объекте выполняли субподрядчики, однако ночами мужчина приходил в парк и обтёсывал неровности фигур, заливал всё новые и новые слои на горки. Его работу так просто не заметить, настолько она кажется незначительной на первый взгляд. На самом же деле его труд куда глубже, куда полезней — он волшебный."},{"kind":"paragraph","text":"Глаза Славы — золотые тарелочки, его ножки — бамбуковые палочки в руках голодного."},{"kind":"paragraph","text":"Шик-шик-шик."},{"kind":"paragraph","text":"А сердечко — его горячий моторчик — барабанит напропалую."},{"kind":"paragraph","text":"Тум-тум-тум."},{"kind":"paragraph","text":"Ребёнок в одиночестве любовался высокими статуями двенадцати месяцев, гладил макушку сидящего на ледяной ветке морозного кота. Иногда поднимал голову, поправляя сползающую шапку, на праздничную ёлку, чья звезда на макушке чуть выше звёзд космических, рассматривал других детей. Слава не искал маму, что потерялась минуты назад, не ждал общения, экскурсий, а просто был сам по себе. Вот он изучает наклон горки поменьше той, с которой катался его отец, стоит рядышком с ледянкой в руках, не решаясь подняться к толпе ребят."},{"kind":"paragraph","text":"В это время его родители-бедокуры выясняли отношения у сугроба, в котором до сих пор сидел отец мальчика, а остальные — родственники и друзья — вообще потерялись из виду. Они отошли в сторону покурить и выпить по глотку горячительного из небольших бутылочек, взятых с собой."},{"kind":"paragraph","text":"— Ты стесняешься, — прозвучал мягкий голос за спиной, который Слава расслышал отчётливо, несмотря на укрытость ушей. — Попробуй, никто тебе против не скажет."},{"kind":"paragraph","text":"Слава обернулся и увидел гладкое лицо седовласого мужчины. Тот был без шапки, но, несмотря на мороз, лицо незнакомца источало сильное тепло. Мужчина улыбнулся, и Слава улыбнулся тоже."},{"kind":"paragraph","text":"— Там нету мне места, — сказал мальчик."},{"kind":"paragraph","text":"— А почему ты так уверен? Смотри! — Мужчина кивнул за спину ребёнка, тот обернулся, и, действительно, выбранная им горка пустовала."},{"kind":"paragraph","text":"— Беги, пока никто не занял, — незнакомец подтолкнул Славу, тот со смехом рванул. Рванул с такой же пульсирующей детской энергией, с какой побежал дома к окну спальни, когда на улице заиграли фейерверки. Но, вспомнив оплеуху отца, тут же замедлился и обернулся к мужчине."},{"kind":"paragraph","text":"— Я тебя понимаю, — тихо сказал тот, улыбаясь. Он сделал шаг навстречу. — Знаешь, я эту горку сам придумал, одна из моих любимых, — он поправил шарф и прикосновением направил ребёнка ближе к горке. — Смотри, какие красивые у неё перила, видишь узоры?"},{"kind":"paragraph","text":"Слава вгляделся в орнамент, который появился буквально только что. До этого узор казался невнятной, покрытой снегом белибердой. Действительно, перила покрывали причудливые очертания девочек с крыльями."},{"kind":"paragraph","text":"— Их называют феями. Волшебные создания, согласись? — незнакомец опустился на колено и провёл пальцем по одной из фигур, смахнув с неё иней. Та встрепенулась и весело затанцевала, словно узнала в мужчине своего создателя. Слава от восторга чуть не упал: он не мог поверить в увиденное. Что-то пропищал, в два прыжка приблизился к чуду и очистил от морозного серебра ещё один рисунок феи. Та точно так же ожила, удивлённо посмотрела на укутанного Славку и улыбнулась."},{"kind":"paragraph","text":"— Давно ты не разговариваешь? — вдруг спросил мужчина."},{"kind":"paragraph","text":"Слава, всё ещё любуясь волшебством, которое сотворил варежкой, кивнул, мол, давно."},{"kind":"paragraph","text":"— Тебя это устраивает?"},{"kind":"paragraph","text":"Кивнул, принялся очищать третью фигурку."},{"kind":"paragraph","text":"— А исправить хочешь?"},{"kind":"paragraph","text":"Мальчик помотал головой."},{"kind":"paragraph","text":"— Слава, скажи мне: что такое плохо и что такое хорошо? Как думаешь?"},{"kind":"paragraph","text":"— Горка. Это хорошо."},{"kind":"paragraph","text":"— О, смотри, заговорил, — улыбнулся седовласый. — Любишь горки?"},{"kind":"paragraph","text":"— Угу, — ответил Слава."},{"kind":"paragraph","text":"— Так почему всё ещё не на ней?"},{"kind":"paragraph","text":"Ребёнок вытер сопливый нос и обернулся назад."},{"kind":"paragraph","text":"— Родители не разрешают, хочешь сказать?"},{"kind":"paragraph","text":"Слава снова замотал головой."},{"kind":"paragraph","text":"— Ты же видишь, их нет здесь. Они сейчас другим заняты."},{"kind":"paragraph","text":"— Ругаются, — произнёс Слава."},{"kind":"paragraph","text":"— Да, и ты это знаешь, — засмеялся мужчина. — Давай так! У тебя, вижу, красивая ледянка есть, но у меня тут… волшебная, — из-под куртки он вытащил что-то совершенно причудливой формы и цвета. — Я её тебе хочу дать. Но при одном условии."},{"kind":"paragraph","text":"Слава почесал нос."},{"kind":"paragraph","text":"— Я обещаю тебе, если ты скатишься вот с этой горки хоть раз, один всего разочек... и повеселишься… Я обещаю, ледянка будет твоей! Не бойся. Сам поймёшь, что ничего веселее ты раньше не пробовал. Но. Сначала на своей скатись."},{"kind":"paragraph","text":"Горка была совсем небольшая: детская, для дошкольников. Чуть ниже отцов, которые обычно торчат рядом и отправляют по ледяному спуску своих трусливых ребятишек, а после, словно гвоздями прибитые, ждут на этом месте, пока те не наиграются. Слава забрался по лесенке, и каждая ожившая фея на перилах ему рукоплескала и подбадривала, а мальчик громко смеялся в ответ. Он присел на вершине, расчистил ледянку, протянул её под попой, сел и несколько раз подпрыгнул, занимая позицию поудобней. После ещё раз посмотрел на седого незнакомца и двинулся к краю. И вот — он покатился."},{"kind":"paragraph","text":"В ту же секунду земля, что была в каком-то метре, оказалась далеко, а в какой-то момент спуск казался бесконечным. Это было совсем не страшно. Мальчик катился и катился, смеялся и смеялся, набирая скорость, пока та не стала постоянной и сверх, но всё это не удивительно, а понятно и знакомо. Такую скорость Слава мог развивать во снах. И там она была для него само собой разумеющимся явлением."},{"kind":"paragraph","text":"Не сосчитать, сколько прошло времени, сколько эмоций пережито, но Славка оказался внизу. Он проехал пару метров по спуску и развалился на льду, хохоча и по-детски захлёбываясь соплями."},{"kind":"paragraph","text":"— Весело, правда? — улыбаясь, спросил мужчина."},{"kind":"paragraph","text":"— Очень! Очень весело, так круто! Хочу ещё, можно ещё?"},{"kind":"paragraph","text":"— А почему нет? Возьми вот эту ледянку, я, как и обещал, дарю её тебе. Только зачем тебе маленькая горка, пойди вон к той, — мужчина указал рукой на самую высокую. И Славкины глаза засияли. — Я тебе обещаю показать мир, который ты так часто видел во снах. И встречу с друзьями, которых ты видишь только тогда, когда закрываешь глаза. Слава, я хочу подарить тебе то, что никто в твоей жизни тебе не даёт: исполнение желаний, сказку, в которой так отчаянно нуждается твоя душа."},{"kind":"paragraph","text":"— Это как? — спросил ребёнок."},{"kind":"paragraph","text":"— Как захочешь — всё, что ты захочешь, всё это будет."},{"kind":"paragraph","text":"— А мама с папой?"},{"kind":"paragraph","text":"Мужчина подошёл к ребёнку и опустился на колено."},{"kind":"paragraph","text":"— Знаешь, а я заметил, что ты так и не ответил на мой вопрос. Что для тебя хорошо, мы услышали, верно?"},{"kind":"paragraph","text":"— Угу."},{"kind":"paragraph","text":"— А что такое плохо — нет."},{"kind":"paragraph","text":"— Я не знаю."},{"kind":"paragraph","text":"— Ты, Слава, многого не понимаешь, верно? Но сердцем своим ты многое знаешь."},{"kind":"paragraph","text":"— Родители? — сдался ребёнок."},{"kind":"paragraph","text":"— Родители, — повторил он. — Ты хочешь, чтобы они не ругались?"},{"kind":"paragraph","text":"— Хочу."},{"kind":"paragraph","text":"— Чтобы любили тебя?"},{"kind":"paragraph","text":"— Да, — улыбнулся Слава."},{"kind":"paragraph","text":"— И чтобы ты их не боялся, хочешь?"},{"kind":"paragraph","text":"Ребёнок смущённо кивнул."},{"kind":"paragraph","text":"— Я тебе всё это обещаю исполнить уже к утру, к утру вернётся любовь к тебе и даже сильнее, но мне от тебя всё ещё кое-что нужно. Чтобы ты скатился вон с той ледяной горки — она моя особая гордость, высочайшая и такая красивая! Посмотри на неё, я долго её строил, она тебе понравится, правда. Ты согласен?"},{"kind":"paragraph","text":"— Угу."},{"kind":"paragraph","text":"— Я хочу показать тебе другой мир. Мой мир, где я уже много лет живу."},{"kind":"paragraph","text":"— А он далеко?"},{"kind":"paragraph","text":"— Всего лишь в конце той горки. И смотри — на ней никого нет. Она полностью в твоём распоряжении."},{"kind":"paragraph","text":"Вступил Слава на лестницу, и перила заходили ходуном. Заиграли на флейтах феи и причудливые создания заплясали, вытесанные во льду и ожившие с приходом мальчика. Звучали знакомые напевы, такие родные и весёлые. Но Слава не мог выделить что-то одно: песнопения смешались. Всё вокруг стремилось угодить ребёнку. И ребёнку это нравилось, то и дело Славка подплясывал, а ступеньки под ним расширялись, оберегая от падения. Где-то сверху включился свет, и мальчик словно оказался на сцене, а взявшиеся из ниоткуда рукоплескания не умолкали."},{"kind":"paragraph","text":"Весь мир сузился до этой горки — за ней всё покрыто мраком, — здесь же праздник и бесконечная радость. Как счастлив он сейчас, как ему хочется танцевать и петь, обнять каждую зверюшку, живущую на перилах, и забыть обо всём."},{"kind":"paragraph","text":"На вершине он огляделся. Вокруг высились древние горы — снежные исполины, — а под ними журчали ручьи, раскинулись равнины с озёрами, зацвели сиреневым поля на горизонте. Солнце показалось совсем близким, а облака можно было разогнать ладонью."},{"kind":"paragraph","text":"— Ты сейчас очень высоко забрался, Слава. Перед тобой весь мой мир, посмотри вниз, — сказал седой мужчина в шарфе. Однако его стиль изменился. Теперь на нём длинный белый балахон. Да и сам мальчик выглядел иначе: ни варежек, ни куртки, ни того бесчисленного множества кофт, которые напялила на него мама. Только ледянка, подаренная незнакомцем. Слава одет так, как ему нравится: белая рубашка и джинсы."},{"kind":"paragraph","text":"Слава посмотрел вниз и увидел аттракционы, огни на колесе обозрения и скачущих туда-сюда акробатов. Всё это он видел и раньше, но где именно, вспомнить не мог, да и не нужно ему. Оно всё здесь, и вместе, и сейчас."},{"kind":"paragraph","text":"— Ты готов? — спросил мужчина."},{"kind":"paragraph","text":"Слава кивнул и сел на ледянку, подполз к краю такой высокой горки, какую он и вообразить не мог, и принялся ждать."},{"kind":"paragraph","text":"— Я тебя сейчас оставлю, но мы с тобой увидимся внизу, хорошо? Тебя ждёт праздник, Слава. Только не бойся. Поверь, теперь всё будет иначе."},{"kind":"paragraph","text":"И когда мужчина исчез, словно дым на ветру, Слава спокойно посмотрел на свои руки, прошёлся пятернёй по волосам несколько раз. Он любил так делать, но ему запрещали — портилась укладка, — улыбнулся и решился."},{"kind":"paragraph","text":"Воздух сотряс тупой удар, будто в океан одновременно упала сотня спелых арбузов. Ледовый городок накрыло инфернальным ором, а родители Славы всё выясняли отношения. Они стояли у полицейского автомобиля: сотрудники патрульной службы явились на ругань супругов и изолировали пьяных от празднующих."},{"kind":"paragraph","text":"В городке отключили музыку, и гости вопросительно двинулись в одном направлении, словно рой. Рации у полицейских неистово затрещали. Уже через секунду вместе с медиками уполномоченные бежали к новогодней ёлке. Мама и папа Славы, воспользовавшись моментом, юркнули в темноту. Кто в какую сторону и зачем — потом и сами не смогут объяснить."},{"kind":"paragraph","text":"— Семьдесят метров, ей-богу, никто не доезжал так далеко!"},{"kind":"paragraph","text":"— А это как случилось, по-вашему? Доехал ведь!"},{"kind":"paragraph","text":"— Семьдесят! Мы после пятидесяти даже лёд не полировали — туда просто невозможно добраться с горки!"},{"kind":"paragraph","text":"— Это ты его семье объяснять будешь! А вон и полиция! Здравствуйте, вовремя вы!"},{"kind":"paragraph","text":"— Что здесь произошло?"},{"kind":"paragraph","text":"— На ребёнка кусок ворот рухнул."},{"kind":"paragraph","text":"— Боже мой…"},{"kind":"paragraph","text":"— Да, мы свидетели, видели — мальчик летел как метеор и врезался, вон они и повалились, стены эти. Страшный удар!"},{"kind":"paragraph","text":"— Такой хруст был, мой брат до сих пор блюёт."},{"kind":"paragraph","text":"— Они ледовые блоки толком не скрепили, нарушение!"},{"kind":"paragraph","text":"— Пошла ты — учить меня будешь, как со льдом работать?!"},{"kind":"paragraph","text":"— Откуда он скатился? С неё, что ли?"},{"kind":"paragraph","text":"— Да, с той горки."},{"kind":"paragraph","text":"— Это невозможно. До неё метров сто, не меньше."},{"kind":"paragraph","text":"— Семьдесят пять, максимум восемьдесят."},{"kind":"paragraph","text":"— Издеваетесь? Его кто-то толкал?"},{"kind":"paragraph","text":"— Да он один летел на ледянке. Да вот она лежит."},{"kind":"paragraph","text":"— Что это за цвет такой?"},{"kind":"paragraph","text":"— Оранжевый?"},{"kind":"paragraph","text":"— Какой оранжевый! Я такой вообще не видел… в дырках вся."},{"kind":"paragraph","text":"— Кто? Кто проектировщик?"},{"kind":"paragraph","text":"— Это я её строил, ей-богу, не вините, мы тысячу раз на выездных её проверяли — тут просто немыслимая ситуация! Так далеко не уехать даже на волшебной ледянке!"},{"kind":"paragraph","text":"— На волшебной, видно, можно."},{"kind":"paragraph","text":"— Дело не в том — доехать или нет, у вас стены не по ГОСТу построены, только заденешь — упадёт!"},{"kind":"paragraph","text":"— Какой ГОСТ, женщина?! Что вы несёте?"},{"kind":"paragraph","text":"— Ребёнка убили — он на вашей совести."},{"kind":"paragraph","text":"— Я и сам в этом убеждён!"},{"kind":"paragraph","text":"— Так, вы родитель?"},{"kind":"paragraph","text":"— Боже упаси, нет…"},{"kind":"paragraph","text":"— А хули тут делаете? Уберите бабу, нахрен! Достала орать."},{"kind":"paragraph","text":"— А родителей правда жалко."},{"kind":"paragraph","text":"— Его пожалей. Где они?"},{"kind":"paragraph","text":"— Ищем ещё."},{"kind":"paragraph","text":"— Ищите! И изолируйте участок — никого сюда не пускать, особенно этих голосистых. Как родственники найдутся, сообщи мне. Я сам с ними буду говорить."},{"kind":"paragraph","text":"Мужчина в полицейской форме достал из внутреннего кармана куртки пачку сигарет, выудил одну и зажёг крикетом огонь. Его руки не дрожали, мысли не толкались одна о другую: он был профессионалом. Но когда подобное случается, даже профессионал приходит к выводу, что он ничего не понимает."},{"kind":"paragraph","text":"Когда спасатели подняли массивную плиту — килограммов двести, не меньше, — под ней, придавленное и припорошённое инеем, лежало совсем крохотное тельце, всё синее, а череп был похож на разодранный гранат."},{"kind":"paragraph","text":"И никого уже не волновало, взъерошенные у мальчика волосы или нет."}]'::jsonb,
  '2026-01-20T12:00:00.000Z'
)
