  published_at = EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd6-idealnaya',
  'Идеальная',
  (SELECT id FROM "Authors" WHERE name = 'Ольга Крушеницкая' ORDER BY id LIMIT 1),
  'mrd6/mrd6-idealnaya.jpg',
  'data:image/jpeg;base64,',
  1379,
  1041,
  'Как-то я подошла к ней, и у меня в руках громко, на всю квартиру, зазвонил телефон. Я вздрогнула от неожиданности, а она и не обернулась, продолжила вытирать пыль. Как же она ходит по городу, не слыша моторы и сигналы ма',
  '[{"kind":"image","path":"mrd6/mrd6-idealnaya.jpg","caption":null},{"kind":"paragraph","text":"Как-то я подошла к ней, и у меня в руках громко, на всю квартиру, зазвонил телефон. Я вздрогнула от неожиданности, а она и не обернулась, продолжила вытирать пыль. Как же она ходит по городу, не слыша моторы и сигналы машин, как отвечает на вопросы незнакомцев, телефонные звонки?"},{"kind":"paragraph","text":"Может, она живёт в божественной тишине или слышит белый шум? Я мало знала о ней: откуда она приходила, где просыпалась по утрам? Куда уходила, знала: к следующему клиенту. Их становилось всё больше и больше, полный город изнеженных белоручек. Зачем убирать, если есть она — идеальная домработница? Не слышит, не говорит, можно записывать голосовые на любые темы, можно включать музыку на всю громкость, можно обсуждать, что угодно."},{"kind":"paragraph","text":"Такая свобода при постороннем — роскошь. Но всё же около неё я всегда ощущала неловкость, что я слышу, а она нет, могу говорить, а она... Как оказалось, она могла говорить, плохо, непонятно, но могла."},{"kind":"paragraph","text":"Она тоже удивилась, что я собираю её звуки в слова. А я и не собирала, если честно, чутьём улавливала смысл. Со мной она могла не только писать, но и говорить, эмоционально, взахлёб, размахивая руками, всем телом передавая суть."},{"kind":"paragraph","text":"Гибкая как лань, высокая, стройная, изящная. Бледная той интеллигентной бледностью, какая бывает у девушек, которые за книгами проводят больше времени, чем на солнце. Не знаю, что у неё было с чтением, просто в голову пришёл образ. Она была белокожей северной казашкой с тонкими костями и нежными чертами лица. Красивая, молодая, модно одетая. Если бы не её особенность, она бы ни за что не зарабатывала на жизнь уборкой."},{"kind":"paragraph","text":"Я легко могу представить её в кафе, изводящую ухажёра бесконечными хотелками. Или в офисе на высоких каблуках, взлетающую в тугой юбке по карьерной лестнице, уверенную и сильную. Она такой и была."},{"kind":"paragraph","text":"Только вместо иностранных языков и музыки она в школьные годы осваивала язык жестов, чтобы из интерната для глухонемых перейти в пугающий мир. Не существовать на грошовое пособие инвалида, а жить как обычный человек."},{"kind":"paragraph","text":"Она приходила в худи, джинсах и кроссовках, переодевалась в рабочие лосины и футболку, доставала свои чудо-тряпочки и, как одержимая, начинала мыть. Знакомая, которая дала контакт Даны, сказала, что та — маньяк уборки, чувствует грязь кончиками пальцев. Я со скепсисом пригласила её и обалдела: она убиралась, как музыканты играют симфонию — слаженно и красиво, квартира после сияла."},{"kind":"paragraph","text":"Той ночью мне приснилось, что на вечеринке муж обнимал девушку, нежно поглаживая её ягодицу. Меня как кипятком ошпарили, никаких сомнений — у них связь, гнев мгновенно ударил в голову, и я метнула бутылку вина, которую несла к столу, в голову мужа. Он охнул, обернулся и... Оказался незнакомым парнем. Схватился за голову, осел, кровь поползла из-под его пальцев по лицу ниже, на рубашку, заливая её. Музыка смолкла. Все, кто был на вечеринке, в ступоре молча переводили взгляды с парня на меня и обратно."},{"kind":"paragraph","text":"Я проснулась, тяжело дыша и лихорадочно соображая, что же делать. Вызывать скорую, на какой адрес? Напряжение отпустило, когда я поняла, что это сон. На часах половина седьмого утра. Попыталась заснуть, но не смогла. Нащупала тапочки и пошла на кухню ставить чайник. Довольный моим ранним подъёмом кот, мешаясь под ногами, добился пакетика корма."},{"kind":"paragraph","text":"Солнце едва поднялось над крышами, но город уже ожил, по дорогам ехали машины, на спортплощадке кто-то делал зарядку, одиночные прохожие спешили по делам. На горизонте дымили две огромные трубы теплосетей. Столько петиций написали, чтобы перестали жечь уголь, перешли на газ, а смог от труб всё так же расползается, скрывая город от неба, превращая алматинцев в безмолвных очевидцев экологической драмы. И, наверное, я провела у окна много времени, потому что позже обычного разбудила своих, и они собирались в спешке, перекусывали на ходу, выливая на меня раздражение. «Не хочу сырники», «где моя рубашка», «опаздываем из-за тебя»."},{"kind":"paragraph","text":"Когда все разошлись в школу и офис, я села работать. Сняв трубку домофона, по привычке спросила: «Кто?» Ответом была тишина. Я вспомнила, что день уборки, и нажала на кнопку с ключом."},{"kind":"paragraph","text":"Дана вошла стремительно, улыбаясь, как будто безумно рада меня видеть. Это для обычных людей добраться до нужного адреса — не задача, а для таких как она — сложности на каждом шагу. Поэтому она светилась как ребёнок, её хотелось сгрести в охапку и зарядиться энергией."},{"kind":"paragraph","text":"Тем более странно было, позже проходя через зал, увидеть её сидящей на подоконнике с опущенной головой. Окно открыто настежь. Она его мыла, а сейчас застыла в позе птицы, которая хочет взлететь. А у нас двадцатый этаж, и Дана — не птица."},{"kind":"paragraph","text":"Меня объял ужас, похожий на тот, что был во сне. Странное явление — сновидения: то ли идут по следам, то ли предсказывают. Я стояла как каменная. Позвать Дану — она не услышит. А если подойти и схватить за руку — можно испугать. Кто знает, в каком вакууме она живёт и как отреагирует?"},{"kind":"paragraph","text":"Она всё сидела и сидела, а меня бросало то в жар, то в холод. Если упадёт, как жить после этого? И как это возможно — мыла окно и решила покончить с собой? Я ведь не знаю о ней ничего, полиция может предположить, что я её выкинула… Хотя за что? Меня с ней ничего не связывает, кроме уборки. Мои руки похолодели, я стояла, боясь пошевельнуться, как будто неловкими движениями могла поколебать пространство и невольно подтолкнуть Дану к опасному шагу."},{"kind":"paragraph","text":"Наконец она задвигалась, поднялась с корточек, развернулась и спрыгнула с подоконника в комнату. Увидела меня и смутилась."},{"kind":"paragraph","text":"— Давно стоишь? — уловила я в протяжном звуке."},{"kind":"paragraph","text":"Я смогла только кивнуть. Она сунула мне свой телефон. На экране — четыре пропущенных."},{"kind":"paragraph","text":"— Послушай, — попросила она мычанием и взглядом."},{"kind":"paragraph","text":"Её телефон зазвонил снова. Дана приложила руку к уху, подталкивая меня ответить."},{"kind":"paragraph","text":"Я нехотя провела зелёный значок вверх."},{"kind":"paragraph","text":"— Привет, киска, ты сегодня свободна? Подъедешь? — мужской голос звучал так, что лёгкая тошнота подступила к моему горлу."},{"kind":"paragraph","text":"Дана рядом буравила вопросительным взглядом:"},{"kind":"paragraph","text":"— Кто это?"},{"kind":"paragraph","text":"Я пожала плечами и отключила вызов. Дана повторила вопрос на бумаге: «Кто звонил?»"},{"kind":"paragraph","text":"«Мужчина, просил подъехать», — написала я."},{"kind":"paragraph","text":"Она нахмурилась, взяла у меня ручку и быстро задвигала ей по бумаге: «Бывший муж на сайте проституток мой номер выложил. Спрашивает, где я, где дети»."},{"kind":"paragraph","text":"«У тебя есть дети?»"},{"kind":"paragraph","text":"«Да, трое»."},{"kind":"paragraph","text":"Ей ведь лет двадцать пять… Когда успела?"},{"kind":"paragraph","text":"«А где они?» — спросила я."},{"kind":"paragraph","text":"«У родственников в другом городе. Муж хочет забрать их»."},{"kind":"paragraph","text":"Чужая беда молчаливо встала передо мной. Я знала, что Дана приехала из Павлодара в Алматы. Думала, потому что здесь больше работы, больше платят, а, получается, она убегает и прячет детей. Я поймала её взгляд — тревожный, но полный доверия, как будто мне ничего не стоит решить её проблемы."},{"kind":"paragraph","text":"«Почему с мужем развелись?» — написала я и передала ей ручку."},{"kind":"paragraph","text":"«Пил много, дети ему мешали, бил их»."},{"kind":"paragraph","text":"«А тебя?»"},{"kind":"paragraph","text":"Дана отрицательно покачала головой, потом сказала едва внятно: «Иногда, один-два раза». И вытянула вверх три пальца."},{"kind":"paragraph","text":"В следующий раз она не пришла вовремя. Написала, что поехала в РОВД с заявлением, что муж её преследует. Появилась в двенадцатом часу. При встрече я не почувствовала обычной её детской радости, движения у неё были резкие, порывистые. И убиралась она суетливо, и писала, писала мне длинные сообщения, бросая пылесос и тряпки посреди комнат, чтобы красивым почерком довольно грамотно выводить на бумаге: нет ли у меня знакомых, которые продают дом, и он стоит пустой. Она готова купить в рассрочку, жить и платить. Ей нужно быть вместе с детьми, муж грозится отнять. Он жестокий человек, она не хочет его видеть, детям нельзя к нему, они должны жить с матерью, и не так, как сейчас. Она будет работать."},{"kind":"paragraph","text":"Я спросила, что сказали в РОВД."},{"kind":"paragraph","text":"«Нет состава, не приняли заявление», — написала она, и крупные слезинки беззвучно потекли по её щекам. От неё так легко отмахнуться: идеальная жертва, доверчивая и безмолвная. Стоит рядом, а её как будто нет, только глаза взывают о помощи."},{"kind":"paragraph","text":"Я кожей ощущала её растерянность. Испытывая стыд за моё благополучие, принесла ей стакан воды. Перебрала в голове знакомых с пустующими дачами: у друга, с которым когда-то у нас не сложилось, недавно умер отец, остался дом, надо ему позвонить, он всегда так рад меня видеть…"},{"kind":"paragraph","text":"Когда она ушла, я вернулась к работе. А ночью стала птицей. Птицей, отгрызающей себе ногу, чтобы освободиться от приковавшего к столбику кольца. Когда всё было кончено, лапка неподвижно распласталась на земле. Я, не чувствуя боли, прыгая на одной лапе, подняла голову к небу и расправила крылья. Но приближающийся топот заставил оглянуться. Через поле бежали мои дети: «Мама, мама!» Как же я могла о них забыть? Прижались, уткнули носики, три счастливых личика, куда я от них? Сомкнула крылья в безмерном объятии. Кандалы, удерживающие меня на земле крепче железных оков, тихо сопели у меня на груди. Теперь всё ещё сложнее, я уже не та красивая птичка, какой была, моё тело стало другим, мне трудно держаться на одной ноге. Я устремила взгляд к звёздам. Тоска о свободном полёте с широко расправленными крыльями вырвалась наружу громким стоном. Я проснулась с головной болью."},{"kind":"paragraph","text":"Никому я не позвонила, потому что это не телефонный разговор, а поводов для встречи не было. Я тогда с головой ушла в творчество, с трудом удерживаясь в семейной жизни. А вскоре Дана исчезла совсем. Не пришла на очередную уборку, мобильный равнодушно сообщил, что номер отключён. Я спросила о Дане у знакомой: «Уехала, сама напишет, когда приедет»."},{"kind":"paragraph","text":"Прошли месяцы, я нашла другую домработницу. В блокноте остались исписанные листы, не вырываю, иногда натыкаюсь. И ещё у меня появилась привычка — замирать, увидев новости о погибших женщинах, судорожно вчитываться в скупые строчки, не Дана ли это, как будто я оставила её в опасности."}]'::jsonb,
  '2026-01-20T12:00:00.000Z'
)
