INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd6-vo-vsem-vinovat-eyzenshteyn',
  'Во всём виноват Эйзенштейн',
  (SELECT id FROM "Authors" WHERE name = 'Денис Колчин' ORDER BY id LIMIT 1),
  'mrd6/mrd6-vo-vsem-vinovat-eyzenshteyn.jpg',
  'data:image/jpeg;base64,',
  1381,
  797,
  'Ершаков вот что запомнил: светлая комната с высоким потолком и большим окном. Возле окна — покрытый светло-коричневой олифой стол. С левой стороны — заправленная бордовой накидкой двуспальная кровать. С правой — комод с ',
  '[{"kind":"image","path":"mrd6/mrd6-vo-vsem-vinovat-eyzenshteyn.jpg","caption":null},{"kind":"paragraph","text":"Ершаков вот что запомнил: светлая комната с высоким потолком и большим окном. Возле окна — покрытый светло-коричневой олифой стол. С левой стороны — заправленная бордовой накидкой двуспальная кровать. С правой — комод с чёрно-белым телевизором и сервант с книгами у стенки. Телевизор включён. На экране творится невообразимое: огромный табун лошадей в белых попонах несётся по заснеженному пространству. На каждой лошади всадник в белом одеянии с чёрным крестом, каждый держит в руке длинный заострённый шест, у каждого на голове перевёрнутое металлическое ведро с крестообразной прорезью."},{"kind":"paragraph","text":"Кто они? Что происходит? Двухлетний Ершаков тревожно вглядывается в экран, не в силах оторваться. Между тем лавина всадников врезается в толпу пеших людей в каплевидных железных головных уборах, тоже с заострёнными шестами в руках. Начинается побоище. Люди кричат, падают в снег. Откуда-то набегают новые. Всё превращается в свалку. Идут динамичные крупные планы. Ершаков заворожённо смотрит, не понимая сути действия, увлечённый водоворотом необычного, блестящего, звенящего. В груди у него зарождается ощущение какого-то непривычного восторга. И всё это вместе: калейдоскоп средневековой схватки, затапливающее чувство восхищения — останется с ним на многие-многие годы, до самого конца."},{"kind":"paragraph","text":"В комнату зашли мама и отец. Поглощённый зрелищем Ершаков их не видит. Только слышит. Память сохранила обрывки фраз: «кино», «Александр Невский»… Пояснения к сюжету, словесные коды. Формулы, позволяющие пройти дальше, проскользнуть в мир, давно исчезнувший, но продолжающий отчаянно пульсировать в параллельной реальности, которую Ершакову ещё только предстоит постичь, на собственной шкуре испытать на прочность связку прошлого и настоящего."},{"kind":"paragraph","text":"Остовы двух разорванных легковушек дымились около сквера республиканского МВД в центре осенней Махачкалы. Кругом сновали полицейские, медики и пожарные. Тротуар был заляпан кровью и клочьями белой пены. С моря приближалась туча, обещавшая дождь. Большинство раненых уже увезли."},{"kind":"paragraph","text":"Ершаков успел записать со слов очевидцев следующее: «…когда взорвалась первая машина, обошлось без пострадавших. У раскуроченного остова собрались правоохранители. В этот момент бабахнула вторая заминированная тачка, припаркованная неподалёку. Силовиков и оказавшихся рядом горожан покосило осколками и поражающими элементами — гайками, болтами, обрезками арматуры. Погибли двое — страж порядка и случайный прохожий. Человек шестьдесят получили различные ранения. Некоторых посекло оконными стёклами, выбитыми ударной волной, метнувшейся по проспекту»."},{"kind":"paragraph","text":"Когда Ершаков примчался, улицу у сквера занимали кареты скорой помощи, сбоку примостилась пожарная. Орали сирены. Перепачканные кровью обалдевшие медики таскали на носилках травмированных, распихивая по салонам. Им помогали гражданские. Заполненные скорые уезжали прочь. Их место тотчас занимали другие."},{"kind":"paragraph","text":"Ершаков принялся фотографировать. Набегавшись, мельком пообщался с кем-то из окровавленных врачей, на пару минут прислонившихся к бортам скорых, с кем-то из легкораненых, сидевших на газоне, с парой-тройкой державшихся тут же зевак. Он старался не наступать на тёмно-красные сгустки, запёкшиеся на асфальте. Между тем пожарные проливали то, что осталось от взорвавшихся автомобилей, и вода, слизывая с тротуара подсыхающую кровь и сукровицу, мутными струями вытекала на проезжую часть."},{"kind":"paragraph","text":"Вечером в прибрежной кафешке Сиражудин спросил его:"},{"kind":"paragraph","text":"— Зачем тебе это? Со мной-то понятно: я правозащитой занимаюсь, живу здесь. Люди вокруг не чужие для меня. А тебе-то зачем? Остался бы у себя в Екатеринбурге. Ходил бы в офис, писал новости уральские. По крайней мере, в безопасности."},{"kind":"paragraph","text":"Ершаков задумался, а затем выдал:"},{"kind":"paragraph","text":"— Во всём виноват Эйзенштейн."},{"kind":"paragraph","text":"— Поясни."},{"kind":"paragraph","text":"— Есть семейное предание. В раннем детстве, когда мы ещё жили в коммуналке, родители телик забыли выключить, и я фильм «Александр Невский» Эйзенштейна глянул случайно. Данный факт серьёзно повлиял на моё сознательное и бессознательное."},{"kind":"paragraph","text":"— А Кавказ тут при чём?"},{"kind":"paragraph","text":"— А при том, что позже абсолютно закономерно я начал интересоваться российской военной историей. И когда в 1999-м Басаев и Хаттаб к вам вторглись, меня окончательно переклинило. А много ли надо пятнадцатилетнему мальчишке? История? Пожалуйста! Война? Пожалуйста!"},{"kind":"paragraph","text":"— И ты пропал…"},{"kind":"paragraph","text":"— Да. Следил за событиями. Делал заметки в толстой тетради. Потом на журфак поступил. Ну а дальше ты в курсе."},{"kind":"paragraph","text":"— Тебе не говорили, что ты просто авантюрист или адреналиновый наркоман? — уточнил Сиражудин."},{"kind":"paragraph","text":"— Говорили, — усмехнулся Ершаков. — Но сие утверждение весьма спорное. Вернее, кусочек правды здесь есть. Но он — лишь небольшая часть диагноза. А сам диагноз, наверное, сложнее."},{"kind":"paragraph","text":"— Для себя-то хоть сформулировал?"},{"kind":"paragraph","text":"— Нет. Пока нет."},{"kind":"paragraph","text":"Подобные ситуации постоянно сопровождали Ершакова. Люди, с которыми он знакомился, рано или поздно интересовались причинами его — странного, на их взгляд, — способа жить. Ершаков, отвечая, отшучивался. Мол, существует фамильная легенда: во всём виноваты режиссёр Сергей Эйзенштейн и актёр Николай Черкасов, сыгравший князя Александра Невского. Собеседники, разумеется, не верили."},{"kind":"paragraph","text":"Вопросы чаще возникали у женщин. Однажды летом ему в мессенджере написала молодая журналистка — среднего роста шатенка накануне развода, мать двоих детей. Она хотела делать документальный фильм про уральских военкоров, и кто-то посоветовал ей обратиться к Ершакову. Встретились в центре города, в парке у станции метро «Динамо». Он рассказал о своих поездках, а дойдя до главного, произнёс:"},{"kind":"paragraph","text":"— В чём причина? Знаете, полную ответственность несёт Эйзенштейн."},{"kind":"paragraph","text":"— Шутите? — удивилась Мария, так её звали."},{"kind":"paragraph","text":"— Ни в коем случае."},{"kind":"paragraph","text":"Впрочем, мир этой истории не узнал. Мария рассчитывала на грант, а зря. Грант не дали. Запись интервью легла на полку."},{"kind":"paragraph","text":"В другой раз Ершаков разговорился с коллегой-азербайджанкой. Миниатюрная, смазливая, похожая на кошку, с хорошими фото в соцсетях, она очень ему нравилась."},{"kind":"paragraph","text":"— Дима, как тебя девушка-то отпускает?"},{"kind":"paragraph","text":"— А у меня нет девушки."},{"kind":"paragraph","text":"— Ну родственники. Им же явно не всё равно."},{"kind":"paragraph","text":"— Знаешь, всё очень сложно. — И далее последовала былина про пагубное влияние кинематографического творчества Эйзенштейна на неокрепшую психику юного Ершакова."},{"kind":"paragraph","text":"Со временем подобные диалоги стали привычны. И когда на корпоративе к нему подсела юная выпускница журфака, недавно перешедшая в их информагентство из филиала федеральной газеты, он, оценивая её большие карие глаза, длинные русые волосы и выразительные, чуть пухлые губы, уже ничему не удивлялся."},{"kind":"paragraph","text":"На ночь бабушка читала Ершакову вместо сказок «Юность полководца» Василия Яна. Вытянувшись худеньким тельцем под одеялом, он внимательно слушал, но понемногу образы князя Александра, дружинников, шведов и немцев смешивались у него в голове, и он засыпал."},{"kind":"paragraph","text":"Книжка была старой, с иллюстрациями художника Ивана Кускова. Вечером, после садика, Ершаков изучал серые невзрачные картинки: вот битва на Неве и упавший с конём на землю ярл Биргер, вот битва на Чудском озере и тонущие в полыньях ливонские кнехты и рыцари — непременно в рогатых шлемах."},{"kind":"paragraph","text":"Книга стала продолжением фильма. Она дополнила изначальные впечатления, расширила их. Ведь где «Юность полководца», там и «Чингисхан», «Батый» и «К \"Последнему морю\"» — серия романов Яна про создание монгольской империи в XIII веке. Ершаков не заметил, как проглотил их от корки до корки, заодно обучившись грамоте. В груди у него уже теплился огонёк страсти."},{"kind":"paragraph","text":"Текст Яна явился второй бациллой, поразившей маленького Ершакова. «Постепенно пёстрое вражеское войско, сперва очень медленно, а затем всё быстрее, двинулось вперёд. Тяжёлым равномерным скоком, казалось, в непреодолимом натиске, приближались немецкие всадники. Уже отчётливо стали видны первые пять рыцарей, мчавшихся, пригнувшись и выставив длинные копья…» Можно было даже не напрягаться. Эйзенштейн услужливо подбрасывал картинку, изменяемую сюжетом книги в нужную сторону."},{"kind":"paragraph","text":"Мало того, изображение Ледовой сечи в изложении режиссёра и писателя как бы застыло во взоре Ершакова, отпечаталось на сетчатке. Он словно наблюдал окружающий мир сквозь прозрачные фигуры бьющихся окольчуженных конников в обрамлении теней копий и щитов. Разумеется, никто не знал этого секрета, ведь даже повествуя о семейном предании, он не раскрывал всех карт, умалчивая о фата-моргане, существующей в его мозгу."},{"kind":"paragraph","text":"Позже Ершаков прочитал биографию автора и нашёл схожие черты. Ян тоже работал военкором — на Русско-японской, в Персии, на Балканах, на румынском фронте Первой мировой, на Урале и в Сибири на стороне белых во время Гражданской. Тоже любил Восток, путешествовал по Центральной Азии. Правда, Ершакову там побывать не довелось, но Северный Кавказ ничем не хуже."},{"kind":"paragraph","text":"Иными словами, мозаика складывалась медленно, формируя характер, взгляды, поступки. Формируя судьбу. Ведь, рассуждая по совести, отговорка про фамильное предание была именно отговоркой. Но при более глубоком рассмотрении оказывалась клубком из разноцветных нитей. Возьмёшься распутывать — сразу провалишься в подёрнутый тонким ледком разлом исторических и культурных ассоциаций и воспоминаний."},{"kind":"paragraph","text":"«Забавная новость», — подумал Ершаков, читая сообщение о том, что в соседней Курганской области установили памятник Александру Невскому. И ладно бы в столице региона, так ведь нет — в какой-то деревне. Инициаторами явились два брата: депутат Госдумы и директор мясокомбината, расположенного в том самом населённом пункте."},{"kind":"paragraph","text":"К пресс-релизу прилагалась фотография: князь Александр в доспехах возвышается на огромном каменном постаменте, придерживая шлем и опираясь на меч. «Какого рожна? Где Невский — и где Зауралье? Они там Эйзенштейна пересмотрели?» — недоумевал Ершаков. Но у мясокомбината с информационным агентством контракт, значит, придётся писать. Никуда не денешься. «Всё ради бизнеса шефа», — говорили обычно в таких случаях в редакции."},{"kind":"paragraph","text":"Ершаков устроился в агентство ещё до поездок на Кавказ. Собственно, оно оказалось на тот момент последним уральским местом работы. Последней каплей, переполнившей чашу. Он пришёл сюда тупо ради денег, дабы немного подзаработать и свалить куда подальше — от малой родины, от скучной повестки, от изнуряющей офисной обязаловки."},{"kind":"paragraph","text":"Само агентство являлось историческим для Екатеринбурга учреждением. Одним из первых в мегаполисе. Оно было слеплено на исходе девяностых на базе муниципального политического движения. Оно отстаивало интересы городской администрации в информационных баталиях с областными СМИ, поддерживающими губернатора. Битвы компроматов кипели такие, что не дай бог. Миниатюрное агентство лавировало в эпицентре схватки, уклоняясь от пудовых кулаков региональных воротил, пытаясь не попасть в объятия легализующихся бандитов, не забывая о своём истинном сюзерене в лице мэрии. Впрочем, к моменту прибытия Ершакова легендарные медиасражения миновали. Агентство влачило жалкое существование, деля помещение на первом этаже сталинки в тенистом квартале в центре Екатеринбурга с упомянутым выше движением, некогда ставшим для него опорной точкой, а нынче полностью захиревшим."},{"kind":"paragraph","text":"Главным редактором агентства был Василий Сергеевич Рыбников. Высокий плотный брюнет под пятьдесят, с пузиком, родом откуда-то с Волги, он ходил на работу в потёртых синих джинсах и старом сером, видавшем виды свитере. Идеальный начальник — весь день играл на компьютере в тетрис или раскладывал пасьянсы, ничего не навязывал, ни о чём не спрашивал, не придумывал идиотских заданий. Иногда складывалось впечатление, будто редакция — сама по себе, а Василий Сергеевич — сам по себе. Порой устраивали небольшие перерывы, и Рыбников рассказывал про жену, состоявшую в пресс-службе транспортной компании, про сына, учившегося на режиссёра в Питере, про будни девяностых, когда агентство занимало комнату в другом здании, а ниже функционировал офис ОПС «Уралмаш» — пожалуй, самой знаменитой преступной группировки Свердловской области того периода."},{"kind":"paragraph","text":"— И вот представьте, — басил Рыбников, — звонят мне знакомые журки из Москвы. Интересуются, как связаться с уралмашскими. А я отвечаю: «Запросто! Записывайте телефон пресс-секретаря». А те охренели: «У них ещё и пресс-секретарь есть?!»"},{"kind":"paragraph","text":"Но верховным руководителем агентства, директором, числился иной человек — Алексеев. Маленький пухленький мужчинка с щёчками, быстро передвигавшийся и без умолку тараторивший, любивший одеваться в костюмы мышиных тонов. Возил его пожилой татарин, ничем иным не занимавшийся, но уверявший окружающих, что трудится в МЧС, и как-то раз даже притащивший ведомственную медаль."},{"kind":"paragraph","text":"На самом деле Алексеевых было двое. Они отвечали за разные направления: старший держал агентство, а второй, такой же кругленький, упитанный брат-близнец, командовал фирмой, управлявшей коммерческой недвижимостью, в основном офисными центрами. Третьей опорой семейного подряда — рекламным агентством — рулила младшая сестра Алексеевых, абсолютно не похожая на них стройная симпатичная брюнетка Таисия."},{"kind":"paragraph","text":"Старший Алексеев боялся всего: конкурентов, чиновников, силовиков. Правда, время от времени, чувствуя поддержку во властных кабинетах, пытался «покусать» кого-нибудь в целях налаживания дальнейших отношений: мол, вы нам — деньги, мы вам — блок на негатив. Например, однажды он велел опубликовать на сайте агентства информацию о проблемах в какой-то новостройке."},{"kind":"paragraph","text":"— Сейчас мы их прижучим, — потирая влажные ладошки, ухмылялся Алексеев."},{"kind":"paragraph","text":"Вечером ему позвонили, и новость молниеносно исчезла. Выяснилось, что к новостройке имели отношение авторитетные люди."},{"kind":"paragraph","text":"Зато в следующий раз Алексееву удалось порезвиться вволю. Поступил заказ — мочить корпорацию, отвечавшую за развитие северной части федерального округа. Требовалось ежедневно звонить депутатам региональных дум, собирая компромат, а затем просить комментарии у пресс-службы корпорации."},{"kind":"paragraph","text":"— Прямо по спискам идите, в алфавитном порядке! — брызгал слюной Алексеев, размахивая руками. — И хуячьте, хуячьте!"},{"kind":"paragraph","text":"Депутаты сперва прониклись и радостно отвечали на вопросы, но уже через несколько дней заподозрили неладное и начали сливаться. Пресс-секретарь корпорации старался соблюдать политес, но в конце концов даже он психанул и проорал в трубку:"},{"kind":"paragraph","text":"— Пусть вам Алексеев комментирует всё это!"},{"kind":"paragraph","text":"Но самая вопиющая история приключилась чуть позже. В городе разгорелся нешуточный скандал: обострилось противостояние между МВД и общественником, боровшимся с наркоторговлей. Правда, ходили слухи, будто активист ведёт свою войну с распространителями дури в интересах определённой криминальной группы, но доказательств никто не предоставил. А поставлено всё было на широкую ногу: команда, офис, база, куда родственники привозили наркоманов на «лечение». Там пациентов приковывали наручниками к кроватям, а после ломки отправляли на трудотерапию."},{"kind":"paragraph","text":"И вот внезапно у одной пациентки обострился хронический менингит. Девушку доставили в больницу города Берёзовского, где она скончалась. Провели экспертизу. Главный врач публично объявил причину смерти гражданки. Видимо, в то мгновение в голове Алексеева щёлкнуло, и он решил вмешаться в конфликт. Ну или просто кто-то опять позвонил."},{"kind":"paragraph","text":"Миссию поручили Ершакову. Когда ему передали детали, он охренел. По словам Алексеева, нужно было сгонять в Берёзовский, найти названного главврача и сделать так, чтобы доктор заявил: девушка умерла от пыток, а пытали её, судя по всему, на той самой базе борцов с наркотиками."},{"kind":"paragraph","text":"— Арматуру брать? — съязвил Ершаков и добавил: — А почему мне поручили? Потому что я с Уралмаша?"},{"kind":"paragraph","text":"Ответа не последовало. Он поехал, отыскал врача. Тот сослался на экспертизу. Мол, никаких сомнений — менингит. Ну и славно. Вернувшись, Ершаков отчитался. Алексеев скривился — выслужиться перед вышестоящими не получалось."},{"kind":"paragraph","text":"«Ну кривись, кривись, — мрачно рассудил журналист. — Я все твои приколы запоминаю, ублюдок»."},{"kind":"paragraph","text":"Толкучка парилась на летнем тяжёлом солнце. Высокий чернявый отец Ершакова нырял в толпу, словно знал тайные пути, вьющиеся в массиве пенсионерских тел, одетых в растянутые треники и футболки, затасканные пиджаки и пожухлые платья. Ершаков, недавно окончивший первый класс, бежал за ним, даже не пробуя припомнить дорогу назад, к спасительной трамвайной остановке. Людские волны бросали его в разные стороны, а он, уцепившись за отцовскую пятерню, зажмурившись, скользил по маршруту, пропитанному запахом пота и перегара."},{"kind":"paragraph","text":"Их выбросило к отмели, представляющей собой ряд лотков с книгами. Чего здесь только не было: детективы, сборники фольклора и рассказов про НЛО, пожелтевшие залежи классики и никому не известных советских писателей, подшивки детских и литературных журналов за разные годы, отрывные календари и труды о вкусной и здоровой пище с тысячами рецептов. Взгляд Ершакова безучастно блуждал по царству макулатуры, пока не споткнулся о скромную книжонку. На белой обложке оранжевая луна висела над чёрным полем, по которому навстречу друг другу неслись монгольский и славянский воины."},{"kind":"paragraph","text":"— Алексей Югов, «Ратоборцы», — прочитал Ершаков и обернулся к отцу."},{"kind":"paragraph","text":"— Давай посмотрим, — сказал тот, открывая аннотацию. — Так, «…повествует о жизни двух величайших защитников русской земли — Данииле Галицком и Александре Невском». Ну что? Берём?"},{"kind":"paragraph","text":"— Ага, — кивнул Ершаков, услыхав заветное имя."},{"kind":"paragraph","text":"Первая часть книги была посвящена Даниилу. В центре сюжета — Ярославская битва августа 1245-го, когда польско-венгерская армия потерпела поражение от русско-половецкого войска, и дальнейшие события отношений Галицко-Волынской Руси и Золотой Орды. Ершаков быстро преодолел её и обратился ко второй."},{"kind":"paragraph","text":"Во второй речь шла о пятидесятых годах XIII века. Прежде всего, о битве на Клязьме в мае 1252-го, то есть о разгроме монголами русской рати, которой руководил князь Андрей Ярославич, младший брат Александра Невского. Само сражение Югов расписал очень красочно. А вот остального юный читатель не оценил. Совсем не оценил."},{"kind":"paragraph","text":"Разочарование накатило на Ершакова. Он сидел, растерянный, на кровати и не мог понять, как можно, написав роман про Невского, обойти стороной Ледовое побоище. Как так можно? Это ведь самое главное! Не книжка, а недоразумение, кощунство! Вот у Эйзенштейна в фильме всё правильно: крестоносцы, таранящий пехоту рыцарский клин, трескающийся лёд. А тут? Кровавое месиво рубки с венграми и татарами. А где эстетика? Где романтика Средневековья? Где иллюстрации, в конце концов?"},{"kind":"paragraph","text":"Однако интересное всё же нашлось."},{"kind":"paragraph","text":"«Рассказывая, Александр вдруг расхохотался…"},{"kind":"paragraph","text":"— Да помнишь, как фон Грюнингена волокли ребята по льду ремнями за ноги?"},{"kind":"paragraph","text":"Хохочет и Андрей. И это не скатерть уже, а чуть припорошённый снежком лёд Чудского озера в тот достопамятный день. А вспомнилось братьям, как ватага неистовых новгородцев во главе с Мишей, пробившись до самого прецептора, свалила фон Грюнингена с коня, и так как закованного в панцирь гиганта трудно было унести на руках, то кто-то догадался захлестнуть за обе панцирные ноги прецептора два длинных ремня, и, ухватясь за них, ребята дружно помчали рыцаря плашмя по льду, в сторону своих: панцирь по льду скользил, как добрые санки с подрезами. И когда уже близ своих были, то кто-то вскочил на стальную грудь, как на дровни, и так проехался на фон Грюнингене, среди рёва и хохота»."},{"kind":"paragraph","text":"Маленькая деталь, но любопытная. Мерцающая вдали, сквозь заросли ордынских интриг. Свежий элемент орнамента, изнутри украшавшего ершаковскую черепную коробку."},{"kind":"paragraph","text":"Ершакову было скучно. Новости про убийства, суды, ДТП, уголовные дела ему давным-давно надоели. Алексеевские идеи раздражали. В перерывах между заметками он читал электронные книги, травил байки с коллегами, выходил на крыльцо подышать свежим воздухом. Возвращаясь за компьютер, просматривал почту и лениво переписывал более или менее пристойные релизы от МВД, СКР или прокуратуры."},{"kind":"paragraph","text":"Зимой, накануне выходных, ему попалось любопытное письмо. Областной департамент охраны природы сообщал о сложной ситуации на севере региона. Там из-за сильных снегопадов и морозов к людям стали выбегать волки. Они пожирали сторожевых собак на деревенских окраинах и даже появлялись на дороге, ведущей в старинный городок Верхотурье. Местные власти посоветовали гражданам без нужды не покидать пределы населённого пункта, особенно по ночам."},{"kind":"paragraph","text":"Ершаков сразу представил вечернюю метель, поглощающую облупленный верхотурский кремль. Куцые огоньки, дрожащие в окнах избушек. На улице пусто, только белая стена из холодного, хрустящего, колюще-режущего волокна. Деревянный мост над промёрзшей рекой Турой превратился в гигантскую продолговатую ледышку. А на выезде в полях и перелесках мелькают быстрые зловещие приземистые тени."},{"kind":"paragraph","text":"Он изложил замысел Рыбникову: сделать репортаж о волчьей блокаде городка."},{"kind":"paragraph","text":"— А от меня-то что требуется?"},{"kind":"paragraph","text":"— Василий Сергеевич, поговорите с Алексеевым. Пожалуйста. Нужны только деньги на бензин, а с департаментом я сам порешаю."},{"kind":"paragraph","text":"— Ну хорошо. Давай попробуем."},{"kind":"paragraph","text":"К счастью, Алексеев согласился, отслюнявив пару тысяч на топливо в обе стороны."},{"kind":"paragraph","text":"Вместе с Ершаковым в командировку отпустили редакционного фотографа Севу. Двухметровый вихрастый брюнет-здоровяк Сева работал в агентстве уже несколько лет. Раньше он жил в Красноярске, но его супругу, занимавшую должность в РЖД, перевели в Екатеринбург, и Сева поехал за ней. Здесь они сняли квартиру. Жена продолжила трудиться в системе, а её избранника приняли в агентство."},{"kind":"paragraph","text":"Выдвинулись на Севиной легковушке по темноте. С проспекта Космонавтов выкатили к Верхней Пышме, а затем свернули на Серовский тракт, прозванный «трассой смерти» из-за частых смертельных аварий. За Нижним Тагилом дорога из четырёхполосной превратилась в двухполосную, разметка из-за снега не просматривалась в принципе, а когда проезжали мимо деревень, Сева матерился, опасаясь, как бы из переулка под колёса не выскочил пьяный сельчанин."},{"kind":"paragraph","text":"— А чего тебе туда приспичило? — спросил Сева про Верхотурье, когда остановились на заправке."},{"kind":"paragraph","text":"— Да ты знаешь, достало в офисе сидеть. Ну сколько можно?"},{"kind":"paragraph","text":"— Я бы в Италию или Испанию сгонял, — принялся мечтать Сева, — пофоткал бы там с удовольствием."},{"kind":"paragraph","text":"— А я бы на войну."},{"kind":"paragraph","text":"— Зачем? — удивился он."},{"kind":"paragraph","text":"— Военкором поработать. Интересно же."},{"kind":"paragraph","text":"— Серьёзно? Мне — нет. Грохнут, не дай бог, и всё. Ни Италии, ни Испании."},{"kind":"paragraph","text":"— Грохнуть-то и здесь могут."},{"kind":"paragraph","text":"— Согласен. Но там вероятность больше."},{"kind":"paragraph","text":"— Всю жизнь дома, что ли, теперь провести?"},{"kind":"paragraph","text":"— Не дома, но рисковать ни к чему, я считаю. Жизнь одна."},{"kind":"paragraph","text":"Верхотурье встретило позёмкой. Лет десять назад, во время учёбы в школе, Ершаков бывал здесь. Правда, летом. Но с тех пор городишко мало изменился. Тот же покоцанный кремль. Те же заброшенные церквушки тут и там. Те же почерневшие от старости деревянные бараки."},{"kind":"paragraph","text":"— Ну как тебе? — съехидничал Сева."},{"kind":"paragraph","text":"— Зашибись! — деланно воскликнул Ершаков."},{"kind":"paragraph","text":"— То-то и оно."},{"kind":"paragraph","text":"Егеря базировались на участке, примыкающем к лесу. Показали своё хозяйство, снегоходы, оружие, снаряжение, найденные капканы. Рассказали о ситуации, о борьбе с волками и браконьерами, накормили варёной картошкой с мясом."},{"kind":"paragraph","text":"— А что за мясо? Кажется, раньше не пробовал такого, — заметил Ершаков."},{"kind":"paragraph","text":"— Мясо хорошее. Кушайте, кушайте, — лукаво улыбнулся главный егерь, краснолицый крепенький мужик в камуфляже."},{"kind":"paragraph","text":"Обратно стартанули после обеда."},{"kind":"paragraph","text":"— Ты заметил, как он улыбался? — не унимался Ершаков."},{"kind":"paragraph","text":"— Да ладно тебе. Нашли, наверное, лося, попавшего в браконьерский капкан, пристрелили, разделали, заморозили. Или уже убитого изъяли, — предположил Сева и засмеялся. — Мясо-то хорошее!"},{"kind":"paragraph","text":"Ближе к Тагилу их нагнал буран. Сева снизил скорость, и они потащились в длинной веренице грузовиков и легковушек, пронизывающей снежное пространство. Ершаков пытался разглядеть окрестности, но видел только включённые фары ползущего впереди джипа, которые светились красно-оранжевым, а затем внезапно обратились в огромные огненные колёса и понеслись куда-то вверх."},{"kind":"paragraph","text":"Откуда взялся тот зелёный том? Да и название пафосное — «За землю русскую». Тем не менее Ершаков одолел «кирпич». Вообще, так получилось, что в детстве и юности он читал в основном исторические романы. Ян, Пикуль, Конан Дойл, Сенкевич, Валентин Иванов, Станислав Пономарёв, Сергей Бородин… И зелёный том. А кто автор? Анатолий Субботин."},{"kind":"paragraph","text":"Субботин, конечно, превзошёл и Яна, и Югова и по объёму, и по глубине изложения. Но, опять же, прямо по Эйзенштейну: «В голубоватой дымке тумана можно различить с русского берега острый клин железного рыцарского полка. Закованные в броню, в рогатых шеломах и шеломах-бочках, с крестовиной спереди, с закрытыми бронёй мордами коней, словно невиданные страшные чудовища, поднявшиеся из ледяных глубин озера, приближаются железные всадники. <…> Но, разорвав чело русичей, меченосцы не повернули коней. Случилось то, чего не предвидели и не могли предвидеть обрадованные лёгкой победой на Лутсне рыцари духовного братства креста и меча. Кони их замешкались в возах, намеренно или случайно оказавшихся позади чела. За возами преграждала путь засека сваленных древесниц. Меж возами, в сучьях древесищ, словно в тенётах, бились рыцари. <…> Следом за железным полком меченосцев вытянулись на русский берег пешие кнехты и холопьи полки. Позади их, на льду Узмени, точно город, несокрушимая стена заднего рыцарского полка. Во главе заднего полка крестоносцев — магистр Ордена, благородный рыцарь фон дер Борг. Рядом с магистром маршал фон Балк, командоры Конрад фон Кейзерлинг и Людвиг фон Гире». И так далее. Словно фильм ещё раз посмотрел."},{"kind":"paragraph","text":"Однако Субботин дал конкретную предысторию конфликта: бросил две приманки — Медвежью Голову и Омовжу. Заинтригованный Ершаков не устоял. Ещё две битвы — пара новых ориентиров. Всё цепляется друг за друга, всё связано. И от этой связи никуда не деться. Если достаточно внимателен, ты не пройдёшь мимо нитей, тянущихся веером, пересекающихся, переплетающихся, точно узор высушенного листа, точно пульсирующая сеть кровеносных сосудов, грибница, космос."},{"kind":"paragraph","text":"По сути, с каждым шагом он дополнял разраставшуюся внутри матрицу. Добавлял текстуры, оттенки. А они не кончались и не кончались. Затейливый орнамент из картинок средневековых летописей, буковок и эмблем сперва полностью покрыл его череп, а затем пополз вниз, охватывая шейный отдел, позвоночник, рёбра."},{"kind":"paragraph","text":"Субботин, кстати, тоже оказался журналистом. Участвовал в Первой мировой и Гражданской. Чередовал административные должности и работу в различных изданиях. В итоге отдал предпочтение писательству. Закономерный мучительный этап, до начала которого большинство не доходит."},{"kind":"paragraph","text":"Летом 2005-го Ершаков, учившийся на журфаке, отправился в Санкт-Петербург на практику четвёртого курса. Поселился у знакомой супружеской пары на юго-восточной окраине, около станции метро «Улица Дыбенко». Муж устанавливал домофоны, а жена трудилась в библиотеке. Ершаков снял у них на три месяца гостиную. Сразу за многоэтажкой тянулся проспект Большевиков, за ним простирался пустырь и текла речка Оккервиль. Иногда по утрам, по пути на работу, ему попадались пьяные негры или латиносы — неподалёку торчали общаги двух университетов: петербургского государственного и метеорологического."},{"kind":"paragraph","text":"Стажироваться Ершакова взяли в газету «Невское время». Редакция располагалась в центре города, на улице Большой Морской, около Исаакиевского собора, в четырёхэтажном доме. В соседнем корпусе — Музей Набокова. У дверей редакции посетителей встречала моложавая блондинка за сорок, выдававшая ключи сотрудникам отделов и записывающая в тетрадь приходящих и уходящих. Ершакова определили в отдел «Общество», поручив переписывать милицейские сводки, бегать на пресс-конференции и прозванивать оперативные инфоповоды. На стене комнаты висело чёрно-белое фото женщины в коротком платье, сидевшей на диване с тлеющей сигаретой в руке."},{"kind":"paragraph","text":"— А это кто? — уточнил однажды Ершаков."},{"kind":"paragraph","text":"— Проститутка, которую мы сюда вызывали, — бесстрастно ответил похожий на писателя и поэта Дмитрия Быкова[1] корреспондент."},{"kind":"paragraph","text":"В целом в редакции царила непринуждённая обстановка, щедро сдабриваемая анекдотами типа: «Идёт мужик по берегу озера. Видит — по пояс в воде рыбак стоит. — \"Ну что, клюёт?\" — \"Нет, не клюёт. Сосёт!\"»."},{"kind":"paragraph","text":"В свободное время Ершаков любил гулять по городу. Однажды его занесло в Александро-Невскую лавру. Арочный вход у названной в честь князя площади оккупировали попрошайки — псевдоветераны, горбатые старухи, «беременные» с подушками вместо живота, обезноженные пропойцы. Все они требовали денег, пива и грозились показать паспорт, видимо, желая доказать, что не являются мошенниками."},{"kind":"paragraph","text":"За аркой лежали прохладные Тихвинское и Лазаревское кладбища, тонкой лентой вилась речка Монастыриха и, наконец, возвышались оранжевые стены лавры. Сама лавра, возведённая в стиле классицизма, бросалась в глаза своими колоннами, башнями, широкими окнами. Внутри, в обитом позолоченным металлом ковчеге, хранились останки Александра Невского. Гробница не произвела на Ершакова никакого впечатления. Больше заинтересовал Казачий некрополь у подножия храма, усеянный захоронениями времён ленинизма-сталинизма."},{"kind":"paragraph","text":"— Надо же, сплошной «совок» в имперской обёртке, — пробормотал он, огибая надгробия бунтовщиков, учёных и партийных функционеров."},{"kind":"paragraph","text":"А вот кто его удивил в своё время, так это советский писатель Борис Васильев. Автор знаменитой повести «А зори здесь тихие». Он же работал над сценарием не менее известного одноимённого фильма 1972 года режиссёра Станислава Ростоцкого. Ершаков со школьной скамьи воспринимал Васильева только в качестве создателя прозаических произведений о Великой Отечественной. Ну о чём ещё мог рассказать ветеран-фронтовик?"},{"kind":"paragraph","text":"Но как выяснилось, не войной единой. В девяностых и нулевых Васильев взялся за исторические романы, посвящённые средневековой Руси. Успел создать несколько — про Олега Вещего, про княгиню Ольгу, про её сына Святослава, про Владимира Крестителя и Владимира Мономаха. И ещё про Александра Невского."},{"kind":"paragraph","text":"Мама Ершакова, работавшая бухгалтером в галантерейном магазине, приносила домой газету, которую присылали в дирекцию по подписке. Ершаков тогда учился в старших классах, кавказская тема уже овладевала им. Он пролистывал издание, вырезая заметки о Чечне, и однажды, пропустив несколько страниц, замер. Там на весь разворот распласталась глава из книги Васильева «Князь Ярослав и его сыновья»."},{"kind":"paragraph","text":"Со стороны судьбы это был запрещённый приём. В тот момент она добила Ершакова точечным выпадом в мозг. Здравствуй, милый Эйзенштейн: «Головной отряд окончательно остановился. Стало чуть посветлее, рыцари стояли совсем близко, и дружинники с удивлением разглядывали боевые шлемы с птичьими когтями, рогами и звериными лапами на некоторых из них». И для закрепления: «Вместе с криками, хрипами и предсмертными стонами из глоток десятков тысяч людей вырывались клубы пара. Они застывали в морозном воздухе, пеленой зыбкого тумана покрывая поле сражения, и красное солнце без лучей вскоре повисло над побоищем, тускло отражаясь в клинках и латах». И для полного счастья: «Это потом объяснили, что бегущие, не знающие особенностей Чудского озера рыцари с ходу вылетели на место, где били ключи, а потому и лёд над ними был тонок. Лёд тонок, а ливонцы тяжелы, да — с бега, да — скопом. <…> И многим из настигающих ливонцев русских дружинников не повезло тоже. Распалённые скачкой кони не слушались поводьев, всадники поздно замечали опасность и десятками летели в последнюю купель вслед за рыцарями»."},{"kind":"paragraph","text":"Про дружинников, разумеется, не по Эйзенштейну. Но какая разница? Препарат «Средневековое военное дело» завершал начатое. Кольчужная мозаика с вкраплениями миниатюрных стрел, шлемов, щитов, мечей, топоров покрыла кости рук и ног Ершакова, забрала всё — от еле уловимого гребешка на макушке черепа до кончиков пальцев."},{"kind":"paragraph","text":"С озера нещадно задувало. Холодный апрельский ветер пробирал насквозь. Ершаков, не вынимая рук из карманов короткой синей куртки, стоял на сером песке, глядя на коричневые камыши и насыщенный синим залив. Где-то здесь, да. Где-то здесь."},{"kind":"paragraph","text":"Чуть позади, на пригорке, громоздился гигантский чёрный бронзовый монумент, изображающий князя Александра Невского, пеших и конных дружинников. Чёрные сосредоточенные лица. Чёрные щиты, шлемы и доспехи. Чёрные лошади. И над ними — застывший, изогнутый, словно парус, чёрный Спас Нерукотворный."},{"kind":"paragraph","text":"Памятник впечатлял. Но что-то заставляло Ершакова скептически морщиться, не доверять скульптурной композиции. Он понимал: монумент — дань героическому мифу, образу, представлению о минувшем. В конце концов, стоило ли ждать чего-то особенного, прорывного от обычной отпускной поездки, от посещения популярного места? Вряд ли. Тем не менее Ершаков не торопился обратно."},{"kind":"paragraph","text":"— Неуютно как-то сегодня, — раздался за спиной мужской голос."},{"kind":"paragraph","text":"Ершаков обернулся и увидел дядьку лет пятидесяти, среднего роста, с русой бородой и открытым лбом, полноватого. Руки тоже в карманах, только куртка длинная, зелёная."},{"kind":"paragraph","text":"— Так апрель ведь, — нехотя произнёс Ершаков."},{"kind":"paragraph","text":"— Ну и что? На прошлой неделе относительно безветренные деньки стояли."},{"kind":"paragraph","text":"— На прошлой неделе меня тут не было."},{"kind":"paragraph","text":"— Я в курсе, — улыбнулся мужчина. — Вы вчера вечером приехали, да? На экскурсию?"},{"kind":"paragraph","text":"— Нет. Просто. Оценить, так сказать."},{"kind":"paragraph","text":"— А меня Максим Григорьич зовут, — не отставал мужчина. — Я историк, работаю здесь."},{"kind":"paragraph","text":"— Очень приятно, — сдержанно промолвил Ершаков, пожимая протянутую сухую ладонь. — Дмитрий."},{"kind":"paragraph","text":"Максим Григорьевич уставился на озеро, а потом внезапно спросил:"},{"kind":"paragraph","text":"— Вас чем зацепило?"},{"kind":"paragraph","text":"— Вы о чём? — не понял Ершаков."},{"kind":"paragraph","text":"— Ну как это о чём? Приехали сейчас. В такую рань уже на озере. Вот меня ещё в детстве Эйзенштейн погубил. А Симонов окончательно в порошок стёр своей поэмой. «В субботу, пятого апреля, / Сырой рассветною порой / Передовые рассмотрели / Идущих немцев тёмный строй…» А у вас как было?"},{"kind":"paragraph","text":"Ершаков снова повернулся к нему, споткнувшись о его карие смеющиеся глаза заговорщика, и неожиданно для самого себя выдохнул:"},{"kind":"paragraph","text":"— Эйзенштейн, сволочь…"},{"kind":"paragraph","text":"Максим Григорьевич заливисто, как-то по-детски, хохотнул."},{"kind":"paragraph","text":"— А потом?"},{"kind":"paragraph","text":"— А потом Ян и вся когорта."},{"kind":"paragraph","text":"— Понятно, — кивнул историк. — А ведь они привирали изрядно. И Сергей Михайлович, прежде всего."},{"kind":"paragraph","text":"— Да?"},{"kind":"paragraph","text":"— Да."},{"kind":"paragraph","text":"— Объяснитесь."},{"kind":"paragraph","text":"— С удовольствием! — воскликнул Максим Григорьевич. — Нам с детства что втирали? Злобный Ливонский орден точил зуб на Святую Русь! Но позвольте. Никакого Ливонского ордена не существовало. Был орден меченосцев, позже влившийся в Тевтонский на правах Ливонского ландмейстерства. Мало того, возьмите школьные карты с границами XIII века. Там нынешние Латвия и Эстония значатся под орденом. Но это упрощённый подход. Потому что Северная Эстония контролировалась Данией, а непосредственно орденские земли рассекались землями католических епископов."},{"kind":"paragraph","text":"— Интересно… А как насчёт вооружения?"},{"kind":"paragraph","text":"— А вот тут Эйзенштейн не слукавил. Стандартная рыцарская экипировка того времени — стёганая одежда с чепцом, кольчуга с кольчужным капюшоном и такими же чулками, подшлемник, шлем топфхельм и гербовая накидка сюрко поверх кольчуги. То есть никаких лат, которыми нас усиленно «кормили» советские писатели."},{"kind":"paragraph","text":"— Да вы ниспровергатель основ. Скрепы расшатываете?"},{"kind":"paragraph","text":"— Никакие это не скрепы и не основы, а сплошное шарлатанство. Вот саму свалку Эйзенштейн неплохо показал. Столкновение конницы и пехоты, суматоха боя, фланговые удары…"},{"kind":"paragraph","text":"— То есть не всё потеряно?"},{"kind":"paragraph","text":"— Не всё, но многое."},{"kind":"paragraph","text":"— Что же ещё?"},{"kind":"paragraph","text":"— Количество. У Эйзенштейна целая кавалерийская бригада снималась. Вы в курсе? И когда романистов наших читаешь, волосы шевелятся на голове. Там ведь железные лавины… Сказочники они, короче говоря. Летопись сообщает про 50 пленных немцев и 400 погибших. Но кем они являлись? Согласно европейским источникам, в битве пали всего двадцать тевтонских рыцарей и шесть угодили в плен. Если учесть, что каждого рыцаря сопровождала свита примерно из десяти бойцов, а во всём Ливонском ландмейстерстве насчитывалось максимум 100 братьев, то можно сделать вывод: в орденском войске на озере числилось от силы 30 рыцарей, наступавших в авангарде, плюс отряд дерптского епископа — вассалов 10–15 с подчинёнными. Ну и эстонское ополчение."},{"kind":"paragraph","text":"— Итого?"},{"kind":"paragraph","text":"— Итого около одной тысячи со стороны ливонцев и порядка полутора — двух тысяч с нашей. Не более. И главное разочарование: скорее всего, никто под лёд не проваливался. В ранних упоминаниях ничего об этом нет. Зато есть в рассказе о битве на реке Омовже, которая произошла за восемь лет до Ледового побоища. Тогда отец Невского Ярослав разбил гарнизоны Дерпта и Оденпе, и часть немцев действительно утонула, будучи оттеснённой на речной лёд. И вероятно, поздние авторы… кхм… позаимствовали данный эпизод для битвы на Чудском."},{"kind":"paragraph","text":"— Ещё скажите, что и спланированного натиска на Русь не было, — саркастически заметил Ершаков."},{"kind":"paragraph","text":"— Так ведь и не было! — опять хохотнул Максим Григорьевич. — Немцы кампанию в 1240-м начали. А если точнее — дерптский епископ и братья из соседних орденских владений. В основном прежние меченосцы. Они Изборск взяли и псковскую рать уничтожили. Там с нашей стороны от 600 до 800 человек полегло. Оттого и Псков сдался — всех защитников поубивали в чистом поле. А весной 1242-го Невский город отбил и в Эстонию пошёл. Но там, кстати, тоже нехорошо получилось. Ливонцы передовой полк раскатали и снова на русский берег двинулись. Ну а дальше — побоище, перемирие... Вообще, я склоняюсь к мысли, что немцами в Ледовом командовал Герман фон Буксгевден, епископ Дерпта. Его люди, к слову, первыми побежали. Зато орденский авангард наши почти полностью перебили. А магистр в рогатом шлеме пусть уж на совести Сергея Михайловича останется."},{"kind":"paragraph","text":"— Ну если у немцев только двадцать рыцарей погибло, то, получается, не побоище, а неизвестно что. Пустяк?"},{"kind":"paragraph","text":"— Почему же? 400 зарубленных и 50 попавших в плен — серьёзные потери по тем временам. Правда, большинство из убитых, естественно, не рыцари, а те, кто их сопровождал, — оруженосцы, сержанты, арбалетчики. Про эстонцев, опять же, не забывайте. Прилично выходит. А вы — пустяк… Хотя, конечно, если брать картину по Балтии в целом, битва на Чудском по масштабности не на вершине рейтинга, а где-то у подножия. Но однозначно круче той же Омовжи. Правда, чем выше по списку, тем жёстче — Раковор, Шауляй, Карузен, Ашераден, Дурбе…"},{"kind":"paragraph","text":"— А вы после таких разборов в истории российской не разочаровались?"},{"kind":"paragraph","text":"— А при чём тут разочарование? — обиженно отпрянул Максим Григорьевич. — Наоборот, ещё интересней стало! Главное ведь — не соответствие неким политическим или идеологическим концепциям. Главное — по возможности детально и достоверно представить происходившее. Сложить мозаику, пазл. Вернуть то первое чувство, возникшее в детстве при просмотре фильма. Понимаете?"},{"kind":"paragraph","text":"Противная каспийская морось сыпала по лицу, заставляя надвигать на глаза капюшон толстовки. Застегнув молнию куртки и поправив на плече рюкзак, Ершаков обернулся на мёрзнущих коллег, вжимающих головы в плечи. Все одеты по погоде — в джинсах, осенних ботинках и куртках поверх свитеров, но, когда ты вынужден стоять на улице, морской ветер и сеющий дождь быстро одолевают. А деваться некуда. Они толпились у забора из листового железа, за которым темнел бетонный недострой. У торчавшего рядом выкрашенного в зелёный одноэтажного здания диспетчерской — сразу за ним мок небольшой дворик с открытыми воротами и асфальтовой дорожкой, ведущей в редакцию газеты, — осматривали тротуар и что-то записывали полицейские и сотрудники Следственного комитета. Тут же была припаркована испещрённая пулевыми отверстиями белая легковушка. Дождевые капли расплывались по её крыше, заднему стеклу, капоту."},{"kind":"paragraph","text":"Недавно здесь расстреляли главного редактора газеты, известного в Дагестане независимого журналиста, не стеснявшегося отвешивать информационные оплеухи чиновникам и силовикам. Он собирался домой и вызвал такси. Как только машина подъехала и редактор спустился, из-за угла выбежали двое в чёрных спортивных костюмах с травматами, переделанными под стрельбу боевыми, и открыли огонь. Таксист мгновенно выскочил из салона и заперся в диспетчерской. Главред попытался укрыться за автомобилем, но, получив несколько ранений, упал лицом вниз. Один из киллеров произвёл контрольный в спину. Затем к месту расправы подлетела серая «Приора», забравшая убийц. Очевидцы вызвали медиков, но пострадавший скончался в карете скорой помощи."},{"kind":"paragraph","text":"Корреспонденты ждали комментариев. Гладковыбритый предпенсионного возраста полковник юстиции в синем мундире, несмотря на дождь, без верхней одежды и фуражки, выйдя за ворота, кивнул телевизионщикам и, когда журналисты обступили его, произнёс дежурное:"},{"kind":"paragraph","text":"— Возбуждено уголовное дело по статьям «Убийство» и «Незаконный оборот оружия». Следствие ведётся. Личности подозреваемых устанавливаются. О мотивах говорить пока рано, отрабатываются разные версии."},{"kind":"paragraph","text":"На него посыпались вопросы."},{"kind":"paragraph","text":"— А правда, что профессиональный мотив является основным?"},{"kind":"paragraph","text":"— Есть информация, будто подозреваемые уже опознаны. Так ли это?"},{"kind":"paragraph","text":"— О чём свидетели говорят?"},{"kind":"paragraph","text":"— Больше ничего не могу сказать, — ответил полковник и повернул к воротам."},{"kind":"paragraph","text":"Ершаков проскользнул вперёд."},{"kind":"paragraph","text":"— Извините. А вы знали убитого?"},{"kind":"paragraph","text":"Полковник резко остановился, смерив его недоумённым взглядом."},{"kind":"paragraph","text":"— Молодой человек, вы о таком спрашиваете…"},{"kind":"paragraph","text":"— И всё же?"},{"kind":"paragraph","text":"Полковник покосился в сторону других репортёров."},{"kind":"paragraph","text":"— Вы не местный, что ли?"},{"kind":"paragraph","text":"— Нет."},{"kind":"paragraph","text":"— Из Москвы?"},{"kind":"paragraph","text":"— Нет."},{"kind":"paragraph","text":"— Видите, как у нас тут? — он кивнул на покрытое пробоинами такси. — Вам дома не сидится?"},{"kind":"paragraph","text":"— Не сидится, — не удержался Ершаков."},{"kind":"paragraph","text":"Полковник замолчал, покачал головой и шагнул во двор."}]'::jsonb,
  '2026-01-20T12:00:00.000Z'
)
