INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd6-fayansovyy-lev',
  'Фаянсовый лев',
  (SELECT id FROM "Authors" WHERE name = 'Владислав Несветаев' ORDER BY id LIMIT 1),
  'mrd6/mrd6-fayansovyy-lev.jpg',
  'data:image/jpeg;base64,',
  1381,
  797,
  'Город спал. До рассвета больше часа. Придорожные фонари бросали жёлтые лучи на кучи смёрзшегося валунами со следами от лопат снега, а те, казавшиеся фиолетовыми, блестели мириадами искр, словно крошечными осколками стекл',
  '[{"kind":"image","path":"mrd6/mrd6-fayansovyy-lev.jpg","caption":null},{"kind":"paragraph","text":"Город спал. До рассвета больше часа. Придорожные фонари бросали жёлтые лучи на кучи смёрзшегося валунами со следами от лопат снега, а те, казавшиеся фиолетовыми, блестели мириадами искр, словно крошечными осколками стекла. Меж сугробов пряталась тропинка, по зиме бывшая единственной дорогой, ведшей от старых деревянных бараков через еловый пролесок в город. По ней шла, скрипя сапогами, старушка в пёстрой каракулевой дублёнке. За собой она волочила пустую тележку на двух колёсиках, которые крутились лишь изредка, когда встречались с рассыпанным песком или реагентом. Шла старушка медленно, холодный ветер мешал ей высунуть лицо из-за плотного, намотанного до самых глаз шарфа, чтобы осмотреться. Лапы пушистых елей, укутанных в белые одеяла, раскачивались от ветра и осыпа́ли шедшую сухими снежинками, приятно коловшими веки."},{"kind":"paragraph","text":"Вид женщина имела скорбный, жалкий. Каждый шаг давался ей с трудом, а множественные одёжки только довершали плеяду препятствий, с которой ей доводилось сталкиваться при ходьбе."},{"kind":"paragraph","text":"Небо, возвышавшееся над мраком леса, было заволочено облаками. А за спиной старушки, у самого горизонта, сияло зарево от теплиц да порой сверкали проблесковые маячки шедших на посадку после учебных вылетов самолётов. Маячков этих она не видела, как и не слышала гул двигателей. Зато впереди уже начала проглядывать автодорога, отрезавшая лес от города."},{"kind":"paragraph","text":"Старушка остановилась, поправила тяжёлую шапку и проморгалась. Она взволнованно вертела головой, пока не обнаружила у себя за спиной в нескольких шагах остов старой осины, едва торчавший из сугроба. Очевидно, он поперву остался незамеченным из-за навалившего за ночь снега. Женщина сняла варежку с левой руки и, взяв её правою, словно метлой, смахнула со своего ориентира перламутровую пудру, затем отряхнула её о подол дублёнки и надела обратно."},{"kind":"paragraph","text":"Через несколько минут старушка добралась до дороги и прошла несколько десятков метров вправо до дорожного знака, означающего место автобусной остановки. Она задрала рукав и взглянула на часы. Её привлёк свет фар выглянувшего из-за поворота автобуса. Свет отразился от знака и с прерывистой постепенностью становился ярче, пока вдруг не погас. Она знала, что после этого автобус прибудет на остановку через двадцать — двадцать пять секунд."},{"kind":"paragraph","text":"Водитель дождался, пока она пройдёт к задним сиденьям, и только потом тронулся, нагоняя упущенные секунды на пологих поворотах. В автобусе было жарко. Очевидно, печка обеспечивала комфорт не пассажиров, зашедших с мороза в зимних ансамблях, а водителя, весь день работавшего в одном свитере."},{"kind":"paragraph","text":"Вот уже несколько лет старушка два раза в неделю ездила на первом утреннем автобусе. Она до того аккуратно соблюдала своё расписание, что водитель иной раз простаивал на её остановке лишних несколько минут, когда не встречался с ней в привычном месте в привычный час. И ещё ни разу не случалось такого, чтобы это было напрасно. Вот проходит минута, две, и знакомая фигура, пыхтя и торопясь, появляется в зеркале. Старушка, расшаркиваясь, с извинениями торопится взобраться по ступеням и суёт ему в руки десятирублёвую монету."},{"kind":"paragraph","text":"Короткий период их общения занял две или три поездки. Водитель хотел перестать взимать с неё плату, а она с упёртой гордостью стояла на том, чтобы продолжить уплачивать. Была она немногословной, косноязычной и оттого казалась подозрительной и невежливой. Бороться он перестал, а по другим вопросам вытянуть из неё хоть слово не удавалось, потому впоследствии они стали изъясняться лишь движениями головы и глаз. Однако нежные чувства он всё же испытывал к ней неизменно как к милому утреннему ритуалу. Примерно такие же чувства она испытывала… нет, не к нему, а к своему осиновому пню у выхода из пролеска."},{"kind":"paragraph","text":"Старушка высадилась, как и обычно, на остановке у продовольственной базы и потащилась по живым лабиринтам пробуждающихся торговых мест к овощным складам. В помещении она опустила шарф, и в лицо ударил приятный тёплый воздух. Несмотря на старость, кожа у неё была гладкой, но до того тонкой, что на ней были видны множественные синие капилляры, испещрявшие её лицо до самых корней седых волос. Особенно выделялся крупный, висевший крюком нос. Он был разукрашен самыми разными цветами, вплоть до зелёного на переносице. Зеленоватая кожа темнела во впадинах у глазниц, где лежали два мелких мутных глаза с голубой радужкой. Старушка всё шевелила безгубым ртом, словно что-то бормотала, однако же это она так чесала коловший от мороза подбородок о каракулевый воротник."},{"kind":"paragraph","text":"Она выглядела совершенно чуждой этому миру снующих туда-сюда и сталкивающихся друг с другом подвижных продавцов и таких же подвижных покупателей. База являла собой едва ли не цельный живой организм, ну или, на худой конец, колонию муравьёв. Кругом был сущий балаган, он подчинялся внутренним законам и порядкам, которые не были очевидны обывателю. На бетонных полах вечно оказывались лужи разного происхождения, но непременно имевшие один и тот же кислый сброженный запах. Верно, бетон за годы эксплуатации впитал в себя эту закваску и стал источать знаменитый аромат при попадании на него любой жидкости, будь то вода или даже отдушка. Такими же вечными казались сырые огрызки гофрированного картона с отпечатанными на них изображениями бананов и пальм, бесконечные паллеты, никогда не пустевшие мусорные корзины. На пенопластовых подложках всегда лежала рыбья требуха, вокруг которой ошивалась свора жирных и сонных котов."},{"kind":"paragraph","text":"Старушка шла привычной дорогой, встречала знакомые лица и прилавки. На приёмке толпились грузовики с бессмысленными в такой мороз рефрижераторами. В воротах виднелось небо, постепенно начинавшее светлеть. За молочным отделом следовал рыбный. В некотором отдалении располагалось несколько столиков возле прилавка с выпечкой и большими термосами с горячим чаем. Ей нравилось смотреть, как озябшие с холода работники поспешно наслаждаются своим завтраком, всё споря, хохоча и ругаясь. Она представляла, как, закупившись, они разъедутся по делам, распространяя жизнь, которая рождалась здесь, на базе, в такую рань. И она ощущала себя частью этой жизни, пускай не столь органичной и шумной, но всё же будто незаменимой. Но больше завтракающих мужчин она любила лавку с корейскими салатами и закусками. Проходя мимо неё, старушка всякий раз засматривалась на экзотические соленья с удивительным ароматом и давала себе слово однажды всё-таки попробовать какую-нибудь особенно инопланетную закуску. За прилавком стояла круглая азиатка в засаленном синем фартуке, которая так же, как и водитель автобуса, любила улыбнуться и кивнуть старушке при встрече."},{"kind":"paragraph","text":"Она прошла всю базу, добираясь до овощного отдела, но и там не остановилась, а дошла до самого тупика, у которого торговали фруктами."},{"kind":"paragraph","text":"Старушка отсчитала пятьсот рублей пятидесятирублёвыми купюрами и купила три с половиной килограмма жёлтых лимонов, каждый из которых любовно выбирала. В пакет отправлялись лишь те, которые, по её ощущениям, обладали тонкой шкуркой и твёрдой мякотью. Азербайджанец, торговавший лимонами, терпел медлительную старушку иной раз минут по десять и с советами лезть перестал уж как год."},{"kind":"paragraph","text":"Нагрузив свою тележку лимонами, она покинула базу и пошла вдоль трассы к автобусной остановке, меся сапогами чёрный от выхлопов снег. Вскоре она поймала набитую маршрутку и, стоя у входа, добралась до центра."},{"kind":"paragraph","text":"Там, возле церкви Святой Троицы, был разбит рынок, на котором, в отличие от базы, торговали розницей. Начинался он у самых ворот церкви. На бордюрах вдоль ограды располагались вязальщицы со своими носками и шапками, дальше тянулись палатки со всякими безделицами, начиная от петард и фейерверков и заканчивая скалками и футбольными мячами. К появлению старушки не все тенты ещё успели натянуть. Продавцы поочерёдно помогали друг другу, борясь с ветром, который норовил вырвать у них из рук брезент. Как всегда, первым ставил палатку продавец рождественских гирлянд. Прохожие ещё продолжали активно скупать иллюминацию, несмотря на то что новый год начался уж три недели тому назад."},{"kind":"paragraph","text":"Сразу за лавкой с гирляндами была небольшая площадь, которую занимали безрукие и безногие музыканты и стая прикормленных голубей. Голуби постоянно толпились в ожидании завтрака. Они до того привыкли к людям, что уворачивались от пинков неохотно и лениво, а иной раз могли схлопотать так, что летели перья."},{"kind":"paragraph","text":"За площадью начинались продовольственные ряды. Туда старушка и держала путь. Она поставила свою тележку на ступени, ведшие в магазин электроники, и стала готовиться к торговле. Для этого у неё был приспособлен деревянный ящик, который она с помощью верёвки крепила к шее, а одним из бортов упирала в живот. Расположив на ящике лимоны и тяжёлый мешочек с мелочью для сдачи, она двинулась меж рядов."},{"kind":"paragraph","text":"Она торговала лимонами по тридцать рублей за штуку. Покупали их у неё чаще из жалости. При всей своей немногословности она умела бойко выкрикивать цену своего товара и настойчиво навязывалась покупателям, отвлекая от выбора продуктов, за которыми они пришли на самом деле. Она сообщала, что её лимоны привезены из солнечной Грузии, что лучше её лимонов на всём рынке не найти, что выращены они были её сестрой без использования вредной химии. Люди потом ещё долго не могли проглотить ком от обиды, что легальные продавцы не прогнали попрошайку."},{"kind":"paragraph","text":"А среди продавцов было заведено негласное правило не трогать «лимонщицу», как её несправедливо называли. Несправедливо потому, что она торговала не только лимонами. В летний сезон она предпочитала зелень, в августе в ход шла кукуруза, которую сборщики позволяли ей нарвать с поля в количествах, не превышающих границы приличия. На рынке она была своеобразной знаменитостью, с которой никто не имел никаких отношений, но и гнать которую никто не спешил, даже если это угрожало некоторыми убытками. Незначительные же убытки из-за «лимонщицы» действительно были. Она была до того настойчивой, что некоторые покупатели шарахались, предпочтя купить те же помидоры в другом месте."},{"kind":"paragraph","text":"Баланс был нарушен вчера. Торговец мясом, тучный мужчина лет пятидесяти, накричал на неё, когда из-за той сбежали покупатели. Чуть позже, остыв, мясник попросил прощения. Она же ничего не ответила, чем тут же вызвала добавочную порцию обзывательств с его стороны. Весь оставшийся день старушка сторонилась его и с опаской поглядывала на него издали. Он был хорошим торговцем, любившим своё дело. Он мог сделать скидку или отдать лучший отруб покупателю, который ему чем-то приглянулся. Много шутил, смеялся, филигранно и, что ли, уважительно обращался с мясом: не швырял его, как прочие мясники, рассекал мякоть в одно резкое и точное движение так, чтобы не оставалось «волны» и «заусенцев» на срезе. Всё у него шло в ход, даже кости, которыми он торговал за гроши. Огрызки же скармливал собакам. Имел он привычку погладить свою лысую голову, иногда забывая, что только что потрогал мясо. На эти случаи у него были припасены влажные салфетки. Старушка весь день, глядя на мясника, злилась и ревновала, что он со всеми вежлив и светел, а с ней повёл себя грубо. Её бесил его сытый и довольный вид. По внешности она сделала вывод, что он сам любитель полакомиться мясом и что-то в этом понимал. Кустистые брови, орлиный нос, карие глаза и акцент выдавали в нём южного человека, а какой мужчина с юга плохо разбирается в мясе? Наторговала она в тот день всё же хорошо, распродав все лимоны, и с чувством выполненного долга поспешила домой."},{"kind":"paragraph","text":"По пути старушка зашла в магазин за продуктами к супу и бутылкой кефира, который страстно любила. В очереди на кассе она столкнулась со своим обидчиком-мясником. Тот, держа в руках корзину, вот-вот собирался выкладывать продукты на ленту, когда она подошла сзади. Сама того не понимая, она будто пыталась обойти его сбоку. Он чувствовал чьё-то присутствие позади и выставлял корпус так, чтобы не дать себя обойти. Старушка же спешила приблизиться к ленте, потому что боялась: товары в руках грозили рассыпаться по полу. Обернувшись, мужчина сразу узнал «лимонщицу». Успевший раздражиться, он пустил её вперёд себя, зачем-то наговорив вдогонку каких-то неприятных колкостей. Она, вся красная, с большим трудом дождалась, пока её рассчитают и быстро двинула домой."},{"kind":"paragraph","text":"Теперешним же утром она решила, что больше не даст себя в обиду, и первым делом двинулась торговать к его лавке. Она с наивной детской дерзостью стала громко декламировать свой однострочный прейскурант, обращаясь не к потенциальным приобретателям лимонов, а к мяснику. Его умиляло поведение старушки, и он, улыбаясь, игнорировал её, продолжая показывать покупателю лоснящуюся мякоть свиной лопатки. Она не унималась и настойчиво зудела над ухом хмурого покупателя, который в конце концов не вытерпел и несдержанно махнул на неё рукой, словно отгонял комара. Она сказала что-то неаппетитное про мясо, и это задело гордость мясника:"},{"kind":"paragraph","text":"— Тётя, брысь отсюда! Ссаными тряпками погоню! — бросил он и тут же обратился к покупателю: — Два кило?"},{"kind":"paragraph","text":"— Он руки-то не моет. Отраву продаёт, — пробормотала старушка."},{"kind":"paragraph","text":"— Иди лесом, ведьма!"},{"kind":"paragraph","text":"Старушка предприняла ещё пару попыток образумить несчастного покупателя, который уже успел полезть в кошелёк за деньгами. Он с прежней несдержанностью отмахнулся от неё, а она в ответ плюнула в его сторону. Мясник схватил головку чеснока, валявшуюся под рукой, и бросил в «лимонщицу». Оскорблённая, но довольная, она медленно заковыляла в сторону, изображая на лице гримасу глубокого несчастья, и радовалась, когда сердобольные свидетели стычки охали и брались за горло при взгляде на неё."},{"kind":"paragraph","text":"В течение дня она мимоходом ещё больше пяти раз проходила возле мясной лавки и внутренне ликовала, когда мясник, завидев её издали, начинал предупредительно махать головой и руками, напуская на себя грозный вид. Она с изяществом подряхлевшей кокетки обходила его стороной, делая вид, будто и не собиралась пастись на его территории. Это был ему такой укол: мол, я, старая, обиды забываю, а ты, мужичок, всё мелочишься, как ребёнок, и думаешь, будто я тут стану истерики закатывать. Больно надо!"},{"kind":"paragraph","text":"Ей доставлял удовольствие не столько факт мучения обидчика, сколько осознание: он ничего не может предпринять против неё. Она безраздельно властвовала над его нервами и упивалась властью. Нищая и продрогшая, она чувствовала себя много уютнее в кишках шумного рынка, чем он в своей лавке на мягком стуле и с тепловой пушкой под ногами."},{"kind":"paragraph","text":"Быстро распродав все лимоны, она поспешила домой, купив по пути бутылку кефира."},{"kind":"paragraph","text":"Её двухэтажный деревянный барак представлял собой убогое зрелище. Должный стать временным жильём для строителей гидроэлектростанции, он вмещал в себе жильцов вот уже шестьдесят с лишним лет. Годы не пощадили его. Весь косой, с поросшей перманентным мхом двускатной крышей, он соседствовал с тремя такими же домами. Все они были выкрашены одинаковой зелёной краской, которая облупилась бог знает сколько лет тому назад. Под слоем зелёной был слой синей краски, под ним ещё более древний красный, и дальше — жёлтый. Расположись цвета не слоями, а последовательно — фасады бы выглядели жизнерадостно. Однако как есть они вгоняли в тоску, а некоторых старожилов при долгом рассмотрении и под приличным градусом шумная палитра вовсе могла погрузить в транс."},{"kind":"paragraph","text":"В подъезд вела тяжёлая металлическая дверь на бессмысленной пружине, которой не хватало упругости для сжатия. Лестница была сложена из подгнивших досок, которые менялись редко. Свежие доски жильцы были вынуждены брать с боем. Каждую зиму потолок на втором этаже сковывался толстой ледяной шишкой, которая, тая по весне, непременно корёжила доски. Возле каждой двери висел почтовый ящик, и почти в каждом торчало по одной-две игнорируемые платёжки. Дом вечно шумел, трещал и скрипел не то от ветра, не то от сковавшего его мороза, не то от топота жильцов."},{"kind":"paragraph","text":"Старушка поселилась тут совсем недавно, два с лишним года назад. Раньше они жили с мужем в самом центре, возле рынка, в небогатой, но приличной квартире с двумя комнатами. Там было уютно: всякая деталь так прикипела к месту, что казалось, будто она там будет вечно. Наживалось всё с трудом и оттого сильно ценилось. Было тесно, но захламлённой квартиру назвать было нельзя. Напротив, светлое пространство казалось уютным и живым. Старушка запомнила свой дом тёплым и защищённым. На фоне всегда что-то шумело, будь то радио или телевизор. Её Федя, вечно что-то читавший, любил отвлечь её от рутины и громко пересказать небылицу, найденную в журнале. Он кричал ей через всю квартиру, а она, шурша в кухне, не вслушивалась в смысл слов, но радовалась, что Федя, увлечённый статьёй, всё же находил в себе силы прерваться и поделиться открытием с нею. Она помнила мягкую кровать с тяжёлыми одеялами и шестью подушками, которые они по три складывали одну на другую. Возле кровати туалетный столик с хрустальной вазой, в которой они хранили всякие погремушки. В стенке на нижней полке она держала иконы, у которых часто молилась на коленях."},{"kind":"paragraph","text":"Детей у них с Федей не нажилось. Но были они счастливы и вдвоём. Два неразлучника, они не могли и дня провести порознь. Её, бывало, клали в больницу на операцию, а он места себе не находил. Всё ходил по дому кругами, плакал и разговаривал с иконами. Потом встречал её, долго и запальчиво рассказывал, что за время её отсутствия успело произойти. И всякая мелочь казалась обоим важной. Мир их был маленький, ограничивался домом, рынком и больницей, но он столь внимательно изучался, чувствовался, что казался бесконечно огромным. У них была целая Вселенная в двух комнатах. В ванной жил паук, которому они дали какое-то смешное имя. Они наблюдали за ним, шутили над ним. Как-то раз, застав его совершенно неподвижным, заволновались, что он умер, а выяснилось, что неподвижной была его сброшенная кутикула. За стеной жила молодая семья с ребёнком, и они с Федей подслушивали за ними и знали про них всё, что проговаривалось вслух. Каждую зиму они размораживали холодильник и относили портящиеся продукты на балкон. Продукты смотрелись там как-то странно-волшебно: непривычно и оттого необыкновенно. Как теплело, намывали до блеска окна, сменяя один другого в ролях мойщика и страховщика. А каждое лето, в начале июля, с утра, пока солнце ещё не успевало раскалить воздух, Федя выносил на улицу ковры и, развесив их на сушилке, упорно выбивал. Она ждала его, пекла блины, переворачивая их прямо пальцами с огрубевшей кожей."},{"kind":"paragraph","text":"Когда Федя умер, Вселенная её схлопнулась. Случилось это вечером, и она была уверена, что сама не доживёт до утра. Она этого не страшилась, но ужасно хотела. Но вот взошло солнце, а она всё ещё на земле. Было так странно, что солнце решило взойти, будто ничего не произошло. Мир её осиротел, стал по-злому бессмысленным. У неё не переставая кружилась голова, и смерть казалась близкой и необходимой. Она не переставала рыдать, обнимая его вещи. Но она продолжала жить, злясь на себя, считая себя предательницей. Разве может человек жить без сердца, без души? К вечеру второго дня ей стало ясно, что может."},{"kind":"paragraph","text":"Ей пришлось заниматься завершением его земных дел. Хоронить его на загородном кладбище — место они предупредительно купили вопреки её протестам — она категорически не желала. Это было далеко, а она хотела, чтоб он был рядом. Всё случилось быстро, скомканно и непонятно. Откуда-то появился человек, который предложил комнату в бараке в обмен на квартиру. Разницы как раз хватало на похороны на центральном кладбище, на поминки, на памятник. Быстро составили бумаги, подписали."},{"kind":"paragraph","text":"Пока она не попрощалась с Федей, никто прогонять из квартиры не стал, сочувствуя её горю, но на пятый день ей помогли сложить и перевезти вещи в барак."},{"kind":"paragraph","text":"Многое дорогое сердцу ушло на помойку. В убогую комнатку ничего не вмещалось. Оставила она при себе лишь самое необходимое, чтобы протянуть оставшиеся ей дни. Среди сохранённых вещей были иконы и фаянсовый бюст льва, который в восемьдесят восьмом из Тифлиса привёз брат Феди. Это была небольшая дурно сделанная скульптурка с крупный кулак, покрытая желтоватой глазурью. Под глазурью на львиный нос и глаза капнули по кляксе чёрной краски. Капнули неосторожно, и оттого лев немного косил. Широко раскрывший пасть, он, очевидно, грозно рычал, но воспринимать его всерьёз с этими косыми глазами было совершенно невозможно. Они с Федей любили этого льва, разговаривали с ним, жалели его, несчастного. Была в нём и прелесть: при правильном угле обзора у льва на ушах и гриве свет создавал волшебные перламутровые узоры."},{"kind":"paragraph","text":"Стоял этот лев теперь всегда возле её скрипучей кушетки, и перед сном она рассказывала ему, чего она узнала нового, как прошёл её день. Он, как всегда, не отвечал, но она знала, что лев всё слышит и радуется, что с ним говорят. А она радовалась, что он её слушал, что был рядом. Случалось, когда ей приснится страшный сон, она поднималась на подушке среди ночи и вспоминала, что рядом стоит их фаянсовый лев, и не могла этому нарадоваться. Она протягивала к нему руки, на ощупь находила его, целовала и прижимала к груди. Намёрзшийся за ночь, лев согревался от тепла её тела, а она тихонько плакала и, бывало, засыпала с ним в обнимку."},{"kind":"paragraph","text":"И вот теперь вечером она, всё ещё возбуждённая, рассказывала льву о стычке с мясником: как он её ругал и как она постояла за себя. Хвалилась, как она оттого вся выпрямилась, посветлела. Лев слушал её с разинутой пастью, а за окном выла вьюга."},{"kind":"paragraph","text":"Мелкие ледышки с треском вреза́лись в дребезжащее окно, подоконник покрывался инеем. Старушка сидела на кровати во мраке комнаты при тусклом свете абажурной лампы и радовалась, что наконец может рассказать льву что-то новое и необыкновенное. Увлечённая, как ребёнок, она не замечала, как мёрзнут её босые ноги на голых досках пола. Убогое жилище показалось ей тем вечером не таким уж гадким и невыносимым."},{"kind":"paragraph","text":"Ночью она долго не могла заснуть: за окном бушевало, что-то не давало ей покоя. Она прокручивала в голове сцены прошедшего дня, держа льва на груди и гладя его. Вдруг, опомнившись, она вскочила с кровати и прошла в прихожую. В темноте она нащупала висящую на гвозде дублёнку, залезла в карман и вытащила оттуда свою выручку."},{"kind":"paragraph","text":"Она убрала её в коробочку, которую держала под стопкой одежды в шифоньере, после чего легла, отогрелась и вскорости уснула."},{"kind":"paragraph","text":"Следующим утром старушка сильно удивила своего водителя, явившись на остановку в неположенный день, но он повёз её без лишних вопросов. На базе она не задерживалась и даже лимоны выбирала без дотошности. Не порадовала кивком кореянку, прошла мимо завтракающих мужчин… Она спешила продолжить свой конфликт с мясником."},{"kind":"paragraph","text":"Он на её появление отреагировал живо и грозно, но уже сам себе смеялся. Было нелепо всерьёз враждовать с «лимонщицей», но она была такой въедливой и приставучей, что у него не оставалось другого выхода, кроме как отвечать ей. Весь день они лаялись. Он не стеснялся в выражениях, а она стала за ним поспевать. Называла его толстым, вонючим, уродливым и глупым."},{"kind":"paragraph","text":"Вечером она со всё возрастающей вовлечённостью рассказывала обо всём льву, задыхаясь, сбиваясь, вспоминая упущенные подробности, особенно те, которые касались её острого злословия. Лев сиял в свете лампы, переливаясь на ушах и гриве всеми цветами радуги."},{"kind":"paragraph","text":"Всю неделю до воскресенья она собачилась с мясником. На четвёртый день она ему надоела. Отвечать он ей стал уже лениво, а потом и вовсе пренебрежительно, жалея её и весело поражаясь, откуда в ней столько азарта и запала. Ей его поддавки не нравились, и она находила всё новые способы уколоть, чтобы вызвать в нём живую реакцию. Стоит отдать ей должное: достать она умела."},{"kind":"paragraph","text":"В воскресенье на рынок она не пришла. Это был день, когда она навещала Федю. Подумывала зайти на обратном пути к мяснику на пять — десять минут, но отогнала эти мысли. А вечером раскаивалась перед львом, что пробыла на могиле не больше двадцати минут: замёрзли ноги."},{"kind":"paragraph","text":"С понедельника она вновь вступила в бой. Мясник уже не давал ей спуску — иной раз мог швырнуть в неё чем-нибудь. Прочие торгаши сперва тяготились конфликтом, старались их примирить, но впоследствии привыкли, а потом и вовсе смеялись над ними, в большей степени, конечно, над мясником. Все симпатии были обращены к нему, но старушку это не расстраивало. Она радовалась вниманию, которым её удостаивали, какого бы сорта оно ни было. Постепенно та стала замечать, что мясник — живой человек, у которого бывает разное настроение. В один день он был резким и злым, в другие же — каким-то задумчиво-печальным. Она же бежала сумасшедший марафон, изо дня в день пребывая в игривом расположении, которое, как глоток свежего воздуха, она почувствовала совсем недавно и никак не могла этой новизной пресытиться. В «печальные» дни мясник ей отвечал слабо, не хлёстко, а она же, словно этого не замечая, давила настойчивее, злее. Она была как разбесившаяся собака, которая не чувствует, когда следует прекратить."},{"kind":"paragraph","text":"Спустя месяц все уже устали, кроме неё. Мясник из одной только жалости посыпал её оскорблениями и проклятиями, изображая при этом весёлый задор. И та уже понимала, что все их склоки — какая-то сама собой сложившаяся неприличная игра, в которую страсть как хотелось играть."},{"kind":"paragraph","text":"Старушка стала браниться со своим врагом уже не так похабно и без прежнего желания уколоть. Всё превратилось в некий ритуал, который успел устареть, но который она, видимо, только одна на всём рынке хотела соблюдать. Потому подход её смягчился. Она чувствовала, что если перегнёт палку, то рано или поздно торговцы устанут и погонят её. Постепенно склока «лимонщицы» и мясника превратилась в нечто абсурдное: взрослый мужчина и старая женщина поносят друг друга на чём свет стоит улыбаясь, с искренней нежностью в голосе."},{"kind":"paragraph","text":"В марте с юга из деревни неожиданно приехал племянник, сын Фединого брата. Она застала его трущимся на пороге её халупы, когда возвращалась домой после очередной баталии со своим врагом. Вид племянник имел уставший и раздражённый. Под ногами у него валялась набитая вещами дорожная сумка."},{"kind":"paragraph","text":"— Где тебя носит, тётка? — несдержанно спросил он."},{"kind":"paragraph","text":"Она пустила его в дом, напоила чаем. Он, отогревшись, смягчился и попросил прощения за грубость. Она радовалась приезду родственника, но уже догадывалась, что визит его связан с какой-то неприятной историей. К тому же он никогда не приезжал один, без своей Люси. Было это полгода назад — больно рано он пожаловал вновь."},{"kind":"paragraph","text":"Опасения подтвердились. Оказалось, что с Люсей они разошлись. Загулял он, и она его погнала. Вот он и явился к тётке, поджавши хвост."},{"kind":"paragraph","text":"За ужином он много и подробно ругал жену, сообщал о своих планах. Говорил, что пробудет у старушки несколько месяцев, пока не найдёт работу и не встанет на ноги. Пил специально припасённую с собою водку и постепенно делался слизью, наматывая сопли на кулак. Она же мало его слушала: всё глядела в окно. Там было до того красивое небо, что она не могла оторвать взгляда. Множество мелких облачков, похожих на отару овец, сбились вместе. Сердцевины их были тяжелы и темны, но края озарялись ярким жёлто-розовым свечением. Они простирались до самого горизонта, где огарок солнца сливал их в однородную густую массу, которая, словно масло, была намазана на до боли яркий и печальный закат. Пока сидели, небо становилось всё более глубоким, облака, темнея, медленно уползали из виду. Клочок неба над горизонтом багровел, растворяясь в ночи, и сливался с острыми верхушками деревьев. И уже нельзя было сказать: небо впивается в них или они в небо."},{"kind":"paragraph","text":"Она попросила у соседа раскладушку для племянника и, когда вернулась с ней, застала того спящим на своей кровати. Будить его она не стала, а постелила себе на раскладушке."},{"kind":"paragraph","text":"Среди ночи проснулась в холодном поту, испугавшись, что он, пьяный, будет ворочаться и ненароком собьёт с пьедестала льва. Тихонько встав, чтоб не разбудить племянника, она взяла скульптуру, легла, обнявшись с нею, и продолжила спать."},{"kind":"paragraph","text":"Вопреки ожиданиям, бытовых хлопот с новым сожителем в её жизни меньше не стало. Напротив — их количество сильно увеличилось. Как будто заехал не один сосед, а целый табор. Возвращаясь с рынка домой, она непременно заставала одну и ту же картину: пьяный племянник спит сидя за столом или лёжа в кровати. Кругом разбросаны бутылки, окурки, раковина забита грязной посудой. Когда она мыла её, он просыпался, подходил и ругался, что она не даёт ему помогать ей по хозяйству. Она отвечала ему что-то по-матерински нежное, а он, насупившись, уходил в комнату и плюхался на кровать."},{"kind":"paragraph","text":"Пенсии старушки стало не хватать на двоих, к тому же кормить вскоре пришлось не только племянника, но и обретённых им друзей, которые чуть не каждую ночь засиживались на кухне до утра, громко споря и распевая песни. Во всей квартире стоял смог — племянник был теплолюбивым и отказывался открывать окно, чтобы проветривать кухню от табачного дыма."},{"kind":"paragraph","text":"Приходилось доставать деньги из коробочки, которую она прятала в шифоньере. Делала она это так, чтобы племянник не прознал о тайнике, а он всё дивился богатству тётки и с шутливой издёвкой называл её Буратино."},{"kind":"paragraph","text":"Бывало, он отсутствовал несколько дней. Говорил, что уходит искать работу, но возвращался ночью с пустыми карманами, без работы, пьяный и побитый, будил старушку и спрашивал, есть ли чего пожевать. Она самоотверженно поднималась и в полудрёме разогревала суп или второе."},{"kind":"paragraph","text":"Общались они мало, не ругались. Она терпеливо сносила его шумность и неблагополучность, сочувствуя его потере. Иногда ей хватало смелости заговорить о том, что ему стоит начать что-то предпринимать, чтобы совсем не захиреть. Но он принимал это в штыки, начинал обороняться, будто на него и впрямь нападали, потом дулся и ещё долго не мог простить тётке бестактность и бесчувственность."},{"kind":"paragraph","text":"К маю она стала всё больше тяготиться сожителем и, не в силах на него повлиять, стала проводить на рынке всё время до самого закрытия. Отдушину она находила в своём бойком сопернике, на котором отрывалась. Мясника, в отличие от племянника, старушка не боялась. Племянник же растерял своих свежеобретённых друзей и стал целыми днями просиживать дома, постепенно превращаясь в совершеннейшего пьяницу."},{"kind":"paragraph","text":"Любимым его занятием был интернет. Он листал приколы по несколько часов кряду и смеялся им с злобной хмуростью. Старушку он обвинял в том, что она до сих пор не провела в свою халупу интернет с вайфаем. Даже у него в деревне был вайфай! Он не понимал глупого упорства, с каким она отказывалась заниматься подведением провода в квартиру. А она была бы рада исполнить его желание, знай она, как к этому делу подступиться. Подсказок с его стороны не поступало. Он лишь злобно объявлял, что из-за её упрямства ему приходится платить за мобильный интернет гораздо больше, чем им пришлось бы платить за вайфай. Бывало, он срывался и начинал кричать на весь дом, если пропадала сеть…"},{"kind":"paragraph","text":"Она стала ценить минуты, когда его не было дома. Она понимала, что в общей картине это к худшему, ведь явится он очень пьяный и агрессивный. Но всё же это стоило времени, которое она могла провести наедине с фаянсовым львом…"},{"kind":"paragraph","text":"Однажды в конце июня она вернулась домой поздно вечером и застала племянника истерично плачущим. Оказалось, Люся поселила в их доме любовника. Он рвал на себе седые волосы и бил себя по лицу. Тётка пыталась успокоить его, говорила добрые слова, гладила и обнимала его, пока не увидела разбросанные по полу белые осколки… Это был её лев."},{"kind":"paragraph","text":"Когда она заплакала, он обиделся на её слёзы и даже ударил её. Как она могла думать о каком-то льве, когда Люся так подло с ним поступила!"},{"kind":"paragraph","text":"Она тщетно пыталась склеить льва. Это было невозможно: фигурка разлетелась на сотни мелких осколков. Старушка держала в руках кусочки его морды и пыталась узнать в них прежние черты. Они были изуродованы, но она, глядевшая на льва в упор многие-многие часы, угадывала почти каждый осколок. Особенно сильно её впечатлил один, на котором остался косящий глаз. Он был размером с ягоду чёрной смородины. С тяжёлым сердцем избавившись от всех прочих, она оставила себе на память этот самый осколок."},{"kind":"paragraph","text":"Старушка проплакала всю ночь. Даже когда ей удавалось заснуть, тут же просыпалась на мокрой подушке. Она старалась особенно не всхлипывать, чтобы не разбудить племянника и не вызвать его гнев. Когда рыдания не удавалось сдерживать, она с усилием утыкалась в подушку, и та поглощала стоны. Измученная, она смогла провалиться в глубокий сон только на рассвете."},{"kind":"paragraph","text":"В десятом часу её разбудил племянник и представил план действий. Он собирался возвращаться в деревню и взять с собою тётку. Ему пришлось извиниться за вчерашнее и уговаривать её, чтобы она согласилась. Он говорил, что не может видеть, как она живёт в этом нищем гадюшнике, а в деревне ей якобы будет хорошо и привольно. На всякий её протест у него была припасена целая порция аргументов. Она в конце концов напомнила ему, что в его доме теперь живёт другой мужчина. Так стало понятно, зачем она ему в деревне. Старушка должна была исполнить роль клея для брака племянника и его Люси. И она согласилась."},{"kind":"paragraph","text":"На следующий же день они ехали в поезде в сторону Ростова. После ждала нелёгкая дорога до Каменска, а оттуда на попутке до деревни."},{"kind":"paragraph","text":"Конечно, никто не обрадовался их появлению, но Люся приняла гостей. Племянник явил тётку Люсе с каким-то странным, одному ему понятным смыслом. Словно старушка была их дочкой и он просит жену одуматься ради неё. План не сработал. Он бросил бравировать тёткой, а она стала чувствовать себя совершенно ненужной и чужой. Никто не обращал на неё внимания. И без неё положению хватало щекотливости: под одной крышей жили муж, жена и любовник. Но и гнать старушку никто не торопился. Она сделалась своеобразным элементом фурнитуры, немым призраком, слоняющимся по дому без дела и смысла. Лишь любовник проявлял к ней редкое сочувствие и иногда веселил её разговорами."},{"kind":"paragraph","text":"Спустя неделю она объявила, что собирается домой. Тактично: сказала, мол, хватит, нагостилась, в гостях хорошо, да дома лучше. Держать её никто не стал. Племянник не пришёл к ней проститься, зная, что она вечером уезжает."},{"kind":"paragraph","text":"До поезда довёз Люсин любовник и даже посадил её."},{"kind":"paragraph","text":"Она сутки тащилась по России, всё глядя в окно и замечая, как изменяется мир. То пред ней стояла беспросветная стена густого леса, то вдруг глазу открывались бескрайние просторы сухих южных полей. Весь путь она думала лишь о своём мяснике, готовила остроты и втайне радовалась, что сумасшедший период её жизни подошёл к концу. Сосед по купе умилялся, когда задумавшаяся старушка вдруг ни с того ни с сего начинала улыбаться."},{"kind":"paragraph","text":"На следующий же день по приезде она отправилась на рынок, даже не заглянув на базу, чтобы закупиться лимонами или зеленью. Она соскучилась по своему врагу…"},{"kind":"paragraph","text":"Невозможно описать пустоту, в которую она провалилась, когда новый мясник сообщил ей, что враг скоропостижно скончался. Подробностей она уже не слышала: в ушах громыхало бешено заколотившееся сердце."},{"kind":"paragraph","text":"Вечером того же дня она умерла. В кулаке она сжимала осколок фаянсового льва. На тумбе возле койки лежала короткая записка, сообщающая, что в коробочке под вещами в шифоньере лежат деньги. В записке она обращалась к племяннику с просьбой, чтобы он на эти деньги похоронил её рядом с Федей."},{"kind":"paragraph","text":"Последнюю волю старушки он не исполнил, а деньги пропил за полгода."}]'::jsonb,
  '2026-01-20T12:00:00.000Z'
)
