INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd6-luchshaya-uchenitsa',
  'Лучшая ученица',
  (SELECT id FROM "Authors" WHERE name = 'Елена Маючая' ORDER BY id LIMIT 1),
  'mrd6/mrd6-luchshaya-uchenitsa.jpg',
  'data:image/jpeg;base64,',
  1379,
  911,
  '— У Жени нет будущего в балете. Эмоциональная девочка. Очень артистичная. Но выворотность…',
  '[{"kind":"image","path":"mrd6/mrd6-luchshaya-uchenitsa.jpg","caption":null},{"kind":"paragraph","text":"— У Жени нет будущего в балете. Эмоциональная девочка. Очень артистичная. Но выворотность…"},{"kind":"paragraph","text":"— Выворотность можно развить, — Женина мама — сама наивность."},{"kind":"paragraph","text":"— Я вас умоляю, за пять лет не развилась, значит, это природное. Женя никогда не сможет стать хорошей балериной. Её не примут в училище. Во-первых, выворотность, во-вторых, лишний вес."},{"kind":"paragraph","text":"— Она уже на диете."},{"kind":"paragraph","text":"Мне показалось, или у неё слёзы в глазах?"},{"kind":"paragraph","text":"Нет, ну вот откуда это стремление: во что бы то ни стало сделать из дочери балерину, даже не понимая, что такое училище-интернат. Да девчонки там друг друга сжирают. Только зря намучается. И по школьным предметам на «красных лебедей» съедет. Потому что там не обучают, а растят рабочих лошадей для сцены."},{"kind":"paragraph","text":"— Думаю, Жене не стоит продолжать заниматься. Разве что для себя, — наверное, жестоко, но зато честно, решила я. — До летних каникул четыре месяца. Этот класс она может закончить, но в следующий я её не переведу."},{"kind":"paragraph","text":"Женька очень сильная. Всё слышала, посмотрела на меня — ледяной взгляд. А потом на занятии работала лучше всех. Особенно у станка."},{"kind":"paragraph","text":"— Батман, батман. Гранд батман, девочки, выше, зафиксировали верхнюю точку. Женя, молодец! Держим спинку, — та же стужа в серых глазах."},{"kind":"paragraph","text":"Но плие плохое. Нет выворотности. Я не хотела, чтобы Женя потратила впустую несколько лет. Хотя с таким характером самое место в балете."},{"kind":"paragraph","text":"После занятий в студии я учила танцевать стриптизёрш. Ибо зарплаты хореографа не хватит даже на несколько пар американских пуантов. Смешно: русская балетная школа, Большой театр, «Щелкунчик», «Лебединое озеро», но лучшие пуанты делают в Штатах, причём на нескольких фабриках. А у нас много лет только в городе на Неве, в одной единственной мастерской. Помню, как однажды родственница привезла из тогда ещё Ленинграда пятнадцать пар. Розовых, атласных. Мне завидовали все девчонки в интернате. Пуанты были дефицитом, лимит на год — двенадцать-тринадцать пар плюс концертные. А тут сразу пятнадцать! Что мне за них только не предлагали! Я чувствовала себя если не Богом, то Дьяволом. Дьяволом в белоснежной пачке."},{"kind":"paragraph","text":"Стриптиз имеет к балету примерно такое же отношение, как шашки к спорту. Если в идеале, нужны внешность, растяжка, гибкость, сильные руки, чувство ритма и огонь в глазах. И всё. Жете, пике, шанжман де пье — да стриптизёрши и не слышали, что это такое. А вот «классная задница», «дай сиськи потрогать», «раздвинь ноги» — каждую ночь. По сути, учу их двигаться для того, чтобы им выкрикивали это как можно чаще."},{"kind":"paragraph","text":"— Я категорически против, чтобы ты там работала, — слышу подобное от мужа практически ежедневно, — с этими шлюхами."},{"kind":"paragraph","text":"— Они не шлюхи. Хотя, может, и шлюхи. Но честные. У них просят голую задницу — они её демонстрируют. А им за это платят, никакого обмана, — отвечаю."},{"kind":"paragraph","text":"— И всё-таки не понимаю, почему ты оставила студию?"},{"kind":"paragraph","text":"— Я много раз говорила."},{"kind":"paragraph","text":"— Неужели только поэтому?"},{"kind":"paragraph","text":"— Не только. Знаешь, я не очень сильный человек. Я намного слабее учениц. Со стриптизёршами это допустимо, с будущими балеринами — нет. Ты даже не представляешь, насколько бывают сильными девочки."},{"kind":"paragraph","text":"Иерархия всюду. В балетном классе прежде всего."},{"kind":"paragraph","text":"— Намочите пол, — требую я. — Поскользнётесь."},{"kind":"paragraph","text":"Ни одна не рвётся полить из лейки. Придётся самой выбрать из этих якобы неженок. Помню, как впервые попросила их — пятилетних, смотрящих на меня сияющими глазёнками, — побрызгать пол. Наперегонки кинулись. Прошёл год, два, три… Стоят. Ни одна не желает позаботиться обо всех. И потом, когда я назову имя, чуть окропит середину, зато щедро намочит собственное место у станка. Неужели я тоже так поступала?"},{"kind":"paragraph","text":"В балетном классе несколько видов изгоев: солистки и такие, как Женя. Без данных. Остальная добротная, но серая масса ненавидит первых, но раболепствует перед ними, снисходительно относится ко вторым, но периодически их подтравливает. Изящные девочки-облака — предмет повышенного внимания мальчишек-ровесников — живут по закону волчьей стаи: они вместе охотятся, но у каждой своя доля добычи."},{"kind":"paragraph","text":"А в стриптизе нет изгоев. Здесь всё по-взрослому. Есть разогрев. Есть самки. Тут все солистки, просто разного качества и с разным заработком. И это совершенно не связано с умением танцевать или величиной бюста, это другое. В клубе Инна одна из лучших. У неё второй размер и неполный шпагат, но мужики пускают слюни уже от одной её походки. И наоборот, Ника: грудь «мечта дембеля» и страсть, пребывающая в вечном анабиозе."},{"kind":"paragraph","text":"Тут не надо поливать пол. Зато надо пользоваться дорогим тональным кремом. У танцовщиц от шеста постоянные синяки, приходится маскировать."},{"kind":"paragraph","text":"— Нет, ну что за сука опять намазалась дешёвкой?! У меня все руки и ноги чёрные! — подобное можно услышать еженощно. — Мне что, сумки обыскать?!"},{"kind":"paragraph","text":"Дешёвый тональный крем окисляется: «шестовичка», крутящаяся после экономной коллеги, оттирается от чёрных пятен весь перерыв."},{"kind":"paragraph","text":"Партия Кармен. Кто из балерин не мечтает исполнить её? Все. Пусть даже на провинциальной сцене. Помню, как сама когда-то трепетала, примеряя алую пачку с чёрным корсажем. Но я-то уже училась в институте. Конечно, это просто бред: взять вариацию из «Кармен-сюиты» для девяти-десятилетней девочки. И дело не в сложности, а в темпераменте. Очень яркая роль. По силам Жене. Но что за Кармен с такой выворотностью? У Жени потрясающие руки: в них и ветер, и пламя, и сумасшествие, и смерть, и полное откровение. Но выворотность…"},{"kind":"paragraph","text":"— Ужасное шассе, — покачала я головой, но Женя продолжила учить движения вслед за Ириной — солисткой, на которую пал мой выбор. — Так, все свободны. Завтра репетируем на сцене. Ирина, Света, Юля Мищенко, Юля Бобылёва, Лариса — к девяти часам. И чтобы были уже разогретые. Остальные к одиннадцати в класс, — я уже начала собираться домой."},{"kind":"paragraph","text":"Женя стояла, прислонившись к двери. Какая бледная! Сколько она сейчас весит?"},{"kind":"paragraph","text":"— Ты кого-то ждёшь? — спросила я."},{"kind":"paragraph","text":"— Вас. Можно я тоже завтра приду к девяти? — И нарочито равнодушно добавила: — Мне всё равно утром нечего делать."},{"kind":"paragraph","text":"Я тронула её за руку."},{"kind":"paragraph","text":"— Ты вообще что-нибудь ешь? Знаешь, нельзя так резко худеть. К тому же…"},{"kind":"paragraph","text":"— Можно я приду завтра к девяти? — повторила она и спрятала руки в карманы куртки."},{"kind":"paragraph","text":"— Женя, понимаешь…"},{"kind":"paragraph","text":"— Я смогу. Вот увидите, смогу, — уверенно сказала она. — Я выучила все движения. Я постоянно репетирую."},{"kind":"paragraph","text":"Мы вышли на улицу. Я обняла Женю за плечи."},{"kind":"paragraph","text":"— Кроме балета есть ещё много чего. Не менее замечательного."},{"kind":"paragraph","text":"— Я знаю, — кивнула она. — Но можно я приду?"},{"kind":"paragraph","text":"— Нет. — К чему давать ненужную надежду? — Ты не справишься. Кармен будет танцевать Ирина."},{"kind":"paragraph","text":"— Справлюсь."},{"kind":"paragraph","text":"— Мне на остановку. До свидания, — улыбнулась я."},{"kind":"paragraph","text":"— До свидания, — уже в спину с металлическими нотками: — Я буду танцевать Кармен! Буду!"},{"kind":"paragraph","text":"На следующее утро Женя пришла к девяти и так старательно занималась, что я даже несколько раз подсказала:"},{"kind":"paragraph","text":"— Подбородок выше… Чуть порезче… Пальчики раскрой, не зажимайся."},{"kind":"paragraph","text":"Для стриптизёрш я не указ. Я и не стремлюсь. Просто работаю над их пластикой и пытаюсь придать номерам больше художественности. Клуб дорогой, и контингент, который приходит сюда отдохнуть, одним сниманием нижнего белья не удивишь. Поэтому каждый номер — история и характер. Но это для меня главное. Главное для танцовщиц — яркий костюм и выгодный ракурс."},{"kind":"paragraph","text":"— Встань боком и прогнись… В чём дело? — репетирую я с Инной."},{"kind":"paragraph","text":"— У меня сбоку грудь плохо смотрится. Маленькая."},{"kind":"paragraph","text":"— Она у тебя в принципе небольшая. Но очень красивая, — сколько раз я уже это говорила?"},{"kind":"paragraph","text":"— Маленькая. Второй размер."},{"kind":"paragraph","text":"— У меня тоже второй. И хватает."},{"kind":"paragraph","text":"— Конечно, хватает, если только мужу показывать! А ты выйди на сцену и попробуй не материться, когда какой-нибудь козёл крикнет: «Снимай трусы и вали отсюда, плоскодонка!» Придушила бы!"},{"kind":"paragraph","text":"— Что бы тебе посоветовать… Или обращай внимание на каждого и выходи на сцену сразу без трусов, или танцуй так, чтобы у всех мужиков ширинки лопнули. Ну так что? — улыбаюсь я."},{"kind":"paragraph","text":"— Как ты там говоришь, боком прогнуться?.."},{"kind":"paragraph","text":"Если есть какой-нибудь балетный бог, то он сотворил чудо. Женя буквально за месяц выросла на несколько голов. Но самое поразительное — куда только делась плохая выворотность? Из аутсайдеров сразу стала явным лидером. И вообще, теперь на сцене смотрелась эффектней многих девочек: высокая, худая, темноволосая, чернобровая. Однажды после занятий подошла ко мне:"},{"kind":"paragraph","text":"— Я собираюсь в августе поступать в училище. Как думаете, у меня есть хоть небольшой шанс?"},{"kind":"paragraph","text":"— Женечка, у тебя миллион шансов. Если хочешь, я поеду с тобой. И вообще, будем перезваниваться, — я нарадоваться этой девочкой не могла."},{"kind":"paragraph","text":"— Правда, поедете? Конечно, конечно, хочу! — Женька запрыгала и захлопала в ладоши."},{"kind":"paragraph","text":"Она была очень внимательной ученицей. Юные балерины вообще-то намного серьёзней обычных сверстниц. И мы — хореографы — относимся к ним, как к взрослым людям. Это бесконечная цепочка, ведь так относились к нам. Хороший хореограф, как и хороший тренер, должен быть всегда немного недосягаем для учеников — я старалась следовать балетному кодексу. Но это детское проявление чувств так тронуло, что я обняла Женю и поцеловала в макушку. А она посмотрела на меня абсолютно счастливыми глазами."},{"kind":"paragraph","text":"Партию Кармен я бы Жене не отдала. Ирина вполне с ней справлялась. Я готовила Женю для других постановок: теперь так многое хотелось с ней успеть. Но за неделю до концерта Ирина заболела бронхитом, пришлось срочно шить второй костюм для Жени. Костюм Ирины не подходил: Женя была намного выше. На последних репетициях танцевала превосходно. Я уже знала, что это моя лучшая ученица. Такие бывают лишь раз за всю карьеру, да и то далеко не у каждого хореографа."},{"kind":"paragraph","text":"В день концерта пришла Ирина. Сказала: просто посмотреть. Они такие, эти маленькие балерины: будут заниматься самоистязанием, глядя, как другие танцуют их партии. Женька — уже загримированная и в костюме — надевала пуанты, чтобы в последний раз повторить сложные места, Ирина сидела на скамейке рядом с ней, а я занималась с другими девочками. Не знаю, о чём они говорили, только Женя подбежала ко мне и попросила:"},{"kind":"paragraph","text":"— Можно мы обе будем солистками? Ира справится. Она же так хотела танцевать Кармен."},{"kind":"paragraph","text":"— Как это обе? — удивилась я."},{"kind":"paragraph","text":"Подошла Ирина."},{"kind":"paragraph","text":"— Я не подведу. Я каждый день занималась, когда температуры не было. Я вам сейчас покажу, — Ирина встала в центр."},{"kind":"paragraph","text":"Ни единой помарки. Как будто и не отсутствовала эти две недели."},{"kind":"paragraph","text":"— А как же ты? — тихонько спросила я у Жени. — Кармен одна, обеим на сцену нельзя."},{"kind":"paragraph","text":"— А меня там и не будет, — сказала девочка и хитро улыбнулась."},{"kind":"paragraph","text":"Уверена, на сцене всё было хорошо, судя по аплодисментам. Я не смотрела на Ирину. Я глядела на Женю. За плотным бархатным занавесом, отделяющим нас от полного зала, было только два человека: Женя — страстная Кармен и я — единственный зритель. Она исполнила потрясающе эту свою первую сольную партию. У меня комок в горле стоял, настолько Женя была божественна. И не нужен был яркий свет софитов и декорации, чтобы разглядеть истинный талант. Я и сейчас закрываю глаза и вижу её — юную Кармен, лучшую ученицу."},{"kind":"paragraph","text":"— И всё-таки я считаю, тебе лучше вернуться в студию, — в сотый раз бурчит муж, глядя, как я собираюсь к «честным шлюхам»."},{"kind":"paragraph","text":"— Я знаю, что ты так считаешь, но я никогда не вернусь, — в сотый раз отвечаю я."},{"kind":"paragraph","text":"Не люблю заниматься с Никой. У неё приличная техника, но всё равно для меня она улитка, зачем-то выползшая на сцену. Прохладная улитка в раковине абсолютного равнодушия. И плевать, быстрая звучит музыка или медленная, дрожит ли воздух от возбуждения, или ночь уже устала от страсти и хочет лишь неги и финального аккорда — улитка не оставляет раковину."},{"kind":"paragraph","text":"— Как можно танцевать с такими пустыми глазами? — Я пытаюсь скрыть раздражение, но выходит плохо. — Представь, что я богатый клиент. Давай, отбери у меня деньги."},{"kind":"paragraph","text":"Улитка вяло ползает сначала по сцене, потом возле меня и предлагает купить по дешёвке бюстгальтер."},{"kind":"paragraph","text":"— Себя продавай, себя, — едва не смеюсь. — Пообещай взглядом, что этой ночью нет запретов. Можно всё, абсолютно всё. Ну же!"},{"kind":"paragraph","text":"Улитка обещает, что не покинет раковину ни за какие деньги."},{"kind":"paragraph","text":"— Знаешь, у меня была ученица, которая в десять лет исполнила Кармен. Я тебе по секрету скажу, не хуже Плисецкой: идеально чисто, с недетским кокетством. В десять лет. А ты голой не можешь станцевать и пяти процентов страсти. Проснись наконец!"},{"kind":"paragraph","text":"Я зову другую стриптизёршу."},{"kind":"paragraph","text":"Ника не уходит, наблюдает, а потом вдруг выдаёт:"},{"kind":"paragraph","text":"— У меня идея. А может, мне тоже стать Кармен? Короткая красная юбочка, корсет…"},{"kind":"paragraph","text":"Хохочу. Ника — Кармен. Надо такое придумать!"},{"kind":"paragraph","text":"После занятий гуляю по стареющему скверу и вспоминаю Женю. Как она сейчас? Я давно не звонила. Надо набрать. Сегодня же."},{"kind":"paragraph","text":"Это было очень жаркое лето. Город плавился на сковороде из асфальта и бетона. В июне я отдыхала на море, а в августе собиралась ехать с Женей в училище. В конце июля начинались занятия в балетной студии — мы должны были всё отшлифовать перед поступлением."},{"kind":"paragraph","text":"Всё-таки странно устроено человеческое сердце. Не удался у меня в то лето отпуск. Была замечательная погода, всё складывалось как нельзя лучше, а я ходила сама не своя и даже несколько раз расплакалась. Просто так, без причины."},{"kind":"paragraph","text":"Отдохнувшие и посвежевшие девочки болтали без умолку. Я показывала аккомпаниатору курортные фотографии. В классе, заглядывая в зеркала, хозяйничало солнце. Такой прекрасный день."},{"kind":"paragraph","text":"Женя опоздала. Поздоровалась."},{"kind":"paragraph","text":"— Переодевайся и к станку."},{"kind":"paragraph","text":"— Можно вас на минуту."},{"kind":"paragraph","text":"Я вышла в коридор."},{"kind":"paragraph","text":"— Я не буду поступать в училище. Извините. Я пуанты принесла. Новые, с того года остались. Вот, — и протянула пакет."},{"kind":"paragraph","text":"— Почему? — от неожиданности я взяла. — Ты поступишь! Если ты думаешь…"},{"kind":"paragraph","text":"— У меня родители в аварию попали. С папой всё в порядке, а мама… Я не буду поступать. Я вообще больше не буду заниматься. Врачи говорят, понадобится много времени… Я не буду, — и опустила глаза. — До свидания! — Она быстро направилась к выходу."},{"kind":"paragraph","text":"— Женя, стой! А как же твоя мечта? И мама так хотела, чтобы ты стала балериной. Как же так? — Проклятые слёзы, не сейчас, не надо. — Может, осенью вернёшься? А на следующий год будем поступать."},{"kind":"paragraph","text":"Женя посмотрела так, будто это мне было десять лет. Улыбнулась."},{"kind":"paragraph","text":"— Вы сами бы смогли танцевать, когда такое? А потом время будет потеряно — навсегда."},{"kind":"paragraph","text":"— Женечка, мама поправится, я уверена. А ты… Ты ведь очень талантливая. Ты лучшая, — я отказывалась верить, что эта девочка оставит балет, цеплялась за любой шанс. — Знаешь, можно окончить школу и поступить в институт культуры, будешь хореографом, как я. Можно после школы…"},{"kind":"paragraph","text":"— Кроме балета есть ещё много чего. Помните, вы сами говорили? — Грустно улыбнулась и ушла, не оборачиваясь."},{"kind":"paragraph","text":"Женина мама полностью восстановилась, но врачи были правы: понадобилось много времени. Ещё несколько лет я преподавала в студии. Некоторые девочки поступили в училище и стали балеринами. Это были очень способные ученицы. Новый набор я делать не стала. Зачем? Зеркала в этом классе никогда уже не отразят девочку, способную в десять лет исполнить партию Кармен, как Женя. Такая ученица бывает лишь единожды. И это счастье, что она у меня была. Лучшая ученица. Настоящая балерина."}]'::jsonb,
  '2026-01-20T12:00:00.000Z'
)
