INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd6-potok',
  'Поток',
  (SELECT id FROM "Authors" WHERE name = 'Юрий Меркеев' ORDER BY id LIMIT 1),
  'mrd6/mrd6-potok.jpg',
  'data:image/jpeg;base64,',
  1381,
  797,
  'Предупреждали вещатели: от Солнца отвалился кусок и устремился к Земле. Придумали странные люди из телевизора магнитные бури и аномалии. Напугали легковерных. И забронировали место под солнцем — так, на всякий случай. Со',
  '[{"kind":"image","path":"mrd6/mrd6-potok.jpg","caption":null},{"kind":"paragraph","text":"Предупреждали вещатели: от Солнца отвалился кусок и устремился к Земле. Придумали странные люди из телевизора магнитные бури и аномалии. Напугали легковерных. И забронировали место под солнцем — так, на всякий случай. Соломку подстелили."},{"kind":"paragraph","text":"Что нам до бабьих сказок? Пошли они все к колдуну Иванову. Тот хоть и врал, но врал порядочно — без подтекста. Честно врал. Не корысти одной ради. Всё какие-то запотевшие лампы за окном разглядывал и транслировал прогнозы на всю Россию. И попадал в точку, а не пальцем в небо, как современные вещатели погоды. Выбритые до блеска, с прямой спиной."},{"kind":"paragraph","text":"Колдуну верил, им — нет. Что может сделаться мертвецу?"},{"kind":"paragraph","text":"Прогнозируют вспышку насилия — о, над этим можно подумать. Зачем?"},{"kind":"paragraph","text":"И почему главный у них удивительно похож на серого кардинала, под мантией которого выпирают звёзды чином не меньше майора?"},{"kind":"paragraph","text":"«Ожидаются солнечные бури, жара, которой не было больше ста лет. Не только метеозависимые — практически все почувствуют недомогание. Возможны обмороки, беспричинная агрессия. В городе увеличится количество суицидов и преступлений психогенного характера» — вывеска на учёном сайте, где любое утверждение кажется смешным. Утверждение случайно угаданных обстоятельств. Оксюморон. Пальцем в небо — о небе. Смешно."},{"kind":"paragraph","text":"И что же это такое — «психогенный характер»? Я знаю: это соломка, которую подстилает товарищ майор."},{"kind":"paragraph","text":"Мне не страшно — я в аду и без инфернальных басен из центра."},{"kind":"paragraph","text":"С весны прошлого года работаю в ритуальном цехе «Поток». Я в потоке, вижу соратников по цеху и тех, кто скоро будет внутри потока, а там окажемся все. Потому что все мы обречены на поток. Это не пальцем в небо, и это не смешно."},{"kind":"paragraph","text":"Режу буквы на камне (как заповедал Бог — «в поте лица своего»), высекаю надгробные надписи, точками расписываю гранит. И пью. Пью много — потому что не пить в потоке нельзя. Многолико и быстро истечение в вечность. Не родник, а фонтан. Точнее — поток. Не успеваем остановить конвейер. Не боги мы. Всего лишь проводники усопших. А их — последнее время — так много, что от одного этого хочется выпить. Не то с горя, не то с радости. Для гравёра «Потока» чужая смерть — не горе, а заработок. А он дополнительным не бывает — его всегда мало, даже когда покойников много. Очень много. И не поймёшь: с радости иногда запиваешь или с горя. Ответ очевиден: не с радости и не с горя, а с тяжёлой работы, на которой невозможно не пить."},{"kind":"paragraph","text":"Мы сами немного похожи на покойников: лица серые от постоянной выпивки, пыльные от мраморной крошки, дубильные от солнечного загара и грязи."},{"kind":"paragraph","text":"Работы много, бригадир выходных не даёт. И вроде как бьётся за трезвость, но пить позволяет — лишь бы не на глазах, не публично то есть, а тайно. Потому что невозможно по десять часов в день рубить одни и те же буковки и не сойти от однообразия и жары с ума. А когда сходишь с ума, рука может дрогнуть — и вместо буквы «О» получится буква «Ё». Брак в работе, в которой брак невозможен. Буквы из памяти не сотрёшь, а входить в вечность с браком не позволяют корпоративная честь и хороший заработок. А ещё архангел, который стоит на пороге вечности: в потоке не может быть ошибок. Брачного змия не пропустит."},{"kind":"paragraph","text":"Бригадир делает вид, что не замечает водки. Готов простить тайно сброшенные в речку расколотые от неосторожных ударов мраморные заготовки плит. Кладбище разбитых памятников — на дне водоёма, подальше от посторонних глаз. Представляю себе шок и трепет какого-нибудь заблудившегося водолаза или полицейского-подводника, который ныряет в поисках тела, а находит целое кладбище. Заранее скорблю о его душевном здоровье."},{"kind":"paragraph","text":"Мой памятник на дне водоёма тоже есть, не исключение."},{"kind":"paragraph","text":"Испортил надпись: «Любим. Помним. Скорбим». Резец слетел с насечки и съехал в кювет. То был день моей последней целомудренной трезвости. После него я начал пить вместе со всеми — влился в коллектив. Старый гравёр Игнат обучал меня искусству рубки буквы «О» и помог расправиться с загубленным памятником. Мне стали сниться кошмары — в них я до тошноты высекал буквы, одни и те же. Мой резец срывал гладкие покровы плиты и углублялся в вечность, путались потусторонние нейронные связи, я вскакивал в холодном поту с постели и тянулся к бутылке. Мужики понимающе кивали — они прошли эту гравёрную инициацию. Если поток вошёл в сон — значит, ты настоящий гравёр «Потока». До этих пор ты лишь ученик."},{"kind":"paragraph","text":"«Не начинайте работать, пока не примете первый стакан», — заповедь от мастера Игната."},{"kind":"paragraph","text":"В августе я нарушил эту заповедь и поранил палец: резец соскользнул и ударил болезненно, кровь хлынула в лунки «Любим. Помним. Скорбим». Лёва, работавший рядом, протянул мне бинт, вату и водку и предложил передохнуть на крыше цеха. Крыша раскалялась, как сковородка в аду, но у нас не было другого места для отдыха. Потому что бригадир Корней мог не заметить водку и расколотую плиту, но всегда видел, когда гравёр отдыхает. Этого он вынести не мог."},{"kind":"paragraph","text":"Лёва — мой приятель: высокий, худой и манерный не по стати. Матом не ругается, носит рыжую бородку, как у дьякона, длинные волосы, пьёт много и не пьянеет. В его крови течёт какое-то армянское высокородие. Учился в университете на химика, бросил, взялся зарабатывать деньги. Говорит, что химия дала ему знания о том, что всё есть поток. Из праха берётся, в прах возвращается. Мудрец."},{"kind":"paragraph","text":"Крыша — единственное место в цеху, где можно укрыться от бригадира. Мы называем час на крыше адмиральским, а два часа — поездкой в Сочи. Тела дымятся от металлического настила, а мы коптимся от водки и усталости."},{"kind":"paragraph","text":"Собственно, в потоке я понял, что водка может спасать и от жары. Стакан тут же выходит через потовые поры, стекает потоком — и становится легче. Это как горячий чай в южных широтах. Только у нас вместо чая — водка. Заметьте: не вино и не пиво, а водка — чистый продукт. Вино и пиво в потоке не спасают, дают временное облегчение, по утрам превращая в «трясунов». А у нас хирургия: руки должны прочно держать молоток или кувалду и бить по скарпелю снайперски. Промахнёшься — получишь отдачу двойную: ужалишь палец до синевы, раскроишь плиту."},{"kind":"paragraph","text":"— Что думаешь делать сегодня? — спросил Лев. — Хочешь, я тебя с подругой Маринки познакомлю?"},{"kind":"paragraph","text":"— У меня есть женщина, Лёвка. Она холодная, как могильная плита, и ждёт меня по ночам трезвым. А я прихожу пьяный, полоумный и горячий, как крыша. Она боится меня, потому что я не могу спать. Руки рубят буквы, а поток сносит крышу. Но Вика терпит меня. За деньги, которые мы тут зарабатываем. Вика считает, что когда-нибудь люди перестанут умирать бешеным потоком и нам дадут отпуск."},{"kind":"paragraph","text":"— Наивная. Моя женщина знает, что поток не остановить. Поэтому мы спим в разных комнатах. Маринка ходит в церковь и молится. Думает, что Бог слышит её молитвы. Она смирилась. Говорит, что через год мы сможем открыть своё дело."},{"kind":"paragraph","text":"— Какое?"},{"kind":"paragraph","text":"— Цех ритуальных услуг."},{"kind":"paragraph","text":"Я рассмеялся, отхлебнул из горлышка и потянулся за бутербродом."},{"kind":"paragraph","text":"— Жара, Лёва, ты сходишь с ума. Какое новое дело в потоке? Ты царь Соломон?"},{"kind":"paragraph","text":"— Мы с Маринкой открыли новый состав для памятников. Лёгкий, пластичный, на века. Она же у меня на химфаке училась. Я тоже."},{"kind":"paragraph","text":"— Хочешь делать памятники из пластика? Заказчики не поймут. Покойникам похер, а живые тебя не поймут. Память должна быть из камня. А у тебя нет денег на покупку резаков и шлифовальных машин. Ты останешься тут, Лёв, и мы будем пресмыкаться перед Корнеем, а жена твоя продолжит ходить в церковь и думать, что её слышит Бог. И я тоже останусь в потоке, хотя и мечтаю совсем о другом."},{"kind":"paragraph","text":"— Может быть, ты прав, а может, и нет. Время покажет."},{"kind":"paragraph","text":"— Людей умирать меньше не будет — это факт. Без работы не останемся — тоже факт. Надо только пережить этот месяц. Чтобы не оказаться внутри потока. Если я там окажусь, заранее прошу тебя, друг, не высекать банальности: «Любим. Помним. Скорбим». А что-нибудь с юмором, типа: «Он шёл по жизни, чуть шатаясь». И, ради Бога, не делай пошлую розочку под надписью."},{"kind":"paragraph","text":"— Не буду, — лениво ответил приятель. — На том свете точно нет ритуальных мастерских?"},{"kind":"paragraph","text":"— Нет, Лёва, там этим занимаются черти."},{"kind":"paragraph","text":"— Так о чём ты мечтаешь?"},{"kind":"paragraph","text":"— Две мечты у меня, и они друг с другом борются. Хочу в деньгах не потерять — и чтобы людей умирало поменьше. Взаимоисключающие вещи. Как считаешь?"},{"kind":"paragraph","text":"— Так глубоко не копаю. Я химик. Из праха взят — в прах вернёшься. Хорошо быть химиком и верить в Бога. Маринка верит в Бога и в химию. Я — только в химию. У нас гармония."},{"kind":"paragraph","text":"Август аномальной жары, без дождей."},{"kind":"paragraph","text":"Город плавится под солнцем."},{"kind":"paragraph","text":"У нас нет выходных."},{"kind":"paragraph","text":"По субботам и воскресеньям наблюдаем с крыши стайки тёмных старух, которые направляются в церковь вымаливать небесную влагу, но Бог почему-то не слышит молитв. Или слышит, но проверяет на преданность — как многострадального Иова. Бабушки в чёрных платках — святые. Дорога до храма — испытание, а ещё выстоять внутри под гласы священника — это подвиг. Меня в храме хватает на пять минут: выскакиваю оттуда пулей. Хоть и работаю с вечностью — наедине с ней могу в тишине выдержать не больше минуты. Минуты молчания. Потом начинаю суетиться и убегать в спасительный шум и работу. Неужели на том свете не будет работы? С ума можно сойти!"},{"kind":"paragraph","text":"Мы лежим с Лёвой на раскалённой крыше и смотрим на стайку старух. Корней приедет вечером. А ближе к ночи мы пойдём с Лёвой в бухгалтерию ругаться: каждую неделю нас стараются обмануть. Выбиваем по тысяче знаков, приходим с бумажками, где всё подсчитано и расписано, а бухгалтерша Машка делает круглые глаза и утверждает, что у неё в табеле не тысяча знаков, а восемьсот и что заплатит она нам только за то, что Корней утвердил в табеле. Бригадир и любовница Машка получают от заказчиков за каждый выбитый знак по сотне, а нам достаётся по четвертаку — «чистая бухгалтерия». Наверное, поэтому Лев хочет открыть своё дело."},{"kind":"paragraph","text":"— Святые старушки. Идут по жаре в храм. Выпрашивают дождь. Мне кажется, они не тому Богу молятся. Или не так молятся. Я не силён в богословии, но слышал, что у нас Бог — это любовь. А зачем у любви что-то выпрашивать? Она всё даёт сама."},{"kind":"paragraph","text":"— Моя Маринка тоже верит, что Бог её слышит."},{"kind":"paragraph","text":"— Нужен дождь, Лёва, иначе мы друг друга перебьём памятниками. С ума сойдём. Представляешь комедию? Гравёры «Потока» перебили друг друга памятниками."},{"kind":"paragraph","text":"— Ты сколько уже работаешь?"},{"kind":"paragraph","text":"— С прошлой весны."},{"kind":"paragraph","text":"— Дождик пойдёт, когда Лёха Лягушатник из соседнего дома начнёт надувать через соломинки лягушек и швырять их под колёса машин. Не видал?"},{"kind":"paragraph","text":"— Нет. Кто это?"},{"kind":"paragraph","text":"— Дурачок местный по прозвищу Леший. Когда старухи проходят мимо его дома в церковь, он будто просыпается. И совершает свои обряды. Безобидные, на первый взгляд. Соседи его в психушку сдают регулярно, а он людей любит. В прошлом году было такое же лето. Лёха набрал на болоте лягушек, надул их через соломинку и пошёл швырять под машины. А утром рванул дождь."},{"kind":"paragraph","text":"— Вот чертило! Неужели правда? Чокнутого лягушатника Бог услышал, а наших праведных бабушек — нет?"},{"kind":"paragraph","text":"— А кто тебе сказал, что бабушки праведнее Лешего?"},{"kind":"paragraph","text":"— Ладно, дружище, нам нужно тоже начать колдовать, иначе от жары загнёмся."},{"kind":"paragraph","text":"— Мы и без того каждый день колдуем. Долбим резцами по камню, считаем знаки — и уже наплевать на слова. А слова хорошие. Нас с тобой, Серый, только черти услышат."},{"kind":"paragraph","text":"— Так я с ними каждую ночь разговариваю."},{"kind":"paragraph","text":"— Это пройдёт. Поработаешь ещё годика три — тебе на всё совсем наплевать будет. И на чертей тоже. Спать станешь как младенец, без снов. Ночью — соска с водкой, утром — соска с водкой, днём — работа с водкой. Скоро трезветь будешь от водки, а пьянеть от трезвости. Признак мастерства. Игнат такой. В трезвости никогда не подойдёт к камню: знает, что скарпель влево или вправо уйдёт."},{"kind":"paragraph","text":"— Пошли в поток. А то Корней явится. У него же чутьё на крышу. На раскалённую крышу цеха. У нас всё наоборот: наверху ад, внизу рай. Хоть какая-то прохлада."},{"kind":"paragraph","text":"Мы с Лёвой спустились вниз осторожнее, чем забирались. И как будто трезвее. Отдохнули славно — теперь можно за дело. Скарпель лежит в мраморной пыли на плитке, на которой выкошены: «Любим. Помним. Ско…». Взял инструмент, добил в два счёта, записал в бумажку ещё 23 знака. Точки и кавычки идут в заработок. А Корней с Машкой у нас эти знаки воруют. Нехорошо зарабатывать деньги на горе людей и ещё своих обворовывать. Но мы с Лёвой люди принципов. Что положено — отдай. Не богохульствуй. Конечно, спрашивать долги с Корнея — это всё равно что биться головой о каменное надгробье: услышишь в ответ лишь хруст собственной лобной доли. Сотрясением отделаешься, если уж больно упрямо начнёшь долбить. Но мы с Лёвой люди принципов."},{"kind":"paragraph","text":"Жара ушла к вечеру, засвистели какие-то пташки ночные. В воздухе разлилась нега. Ночной город обожаю. Идёшь по проспекту пешком, ноги и руки такую силу чувствуют, что, кажется, взял бы и землю свернул, как Архимед. Дайте мне только точку опоры. И никакого похмелья — потому что в крови ещё гуляет водка с раскалённой крыши, бродит по телу, как брага в самогонном аппарате. И хорошо на душе, радостно — как у молитвенных бабушек, если молебен принёс дождь. Нет дождя — вечерами земля отдыхает. Остывает ненадолго. Наверное, и крыша приятно прохладная — после двадцати одного не был."},{"kind":"paragraph","text":"У Машки в конторе свечение, как у монашки в келье. Сидит, красавица, над бухгалтерскими премудростями, колдует. Машка — тёмная худая девица, похожая на актрису из сериала про цыган. Глаза огромные, влажные и ласкающие, но последнее предназначено женатому Корнею. И что она в нём нашла? Пузо навыпуск, плечи как церковный колокол — не обхватишь, — рыжие усы подковкой и наглый взгляд. Ни дать ни взять — ростовщик с большой дороги. В прошлом боцман, в девяностые сошёл на берег с тремя контейнерами импортных шмоток, продал их, прикупил оборудования, договорился с бандитами, сделал кому надо несколько бесплатных захоронений — и вот он, почти царь иудейский. Командир похоронной армии."},{"kind":"paragraph","text":"— Привет, Масяня. Как дела?"},{"kind":"paragraph","text":"Красавица принимает наши бумажки и быстро переносит циферки в табель — так быстро, чтобы мы не заметили синевы под её левым глазом."},{"kind":"paragraph","text":"— Корней? — спрашивает Лёва."},{"kind":"paragraph","text":"— Жена его приезжала. Скандал устроила. Доработаю лето — уйду в школу. Детей учить снова буду. Надоело всё."},{"kind":"paragraph","text":"— По какому предмету училка? — интересуюсь."},{"kind":"paragraph","text":"— По математике."},{"kind":"paragraph","text":"— Тогда понятно, почему бухгалтер. Сегодня все наши знаки оплатишь? Не как обычно?"},{"kind":"paragraph","text":"— Сегодня всё оплачу. Надоело. Бухгалтерия надоела, жена Корнея — всё надоело. Кондиционер не может купить, бизнесмен хренов! Боцманом был — боцманом остался. Широты в нём много, глубины нет. Злые все."},{"kind":"paragraph","text":"— Потерпи, Масяня, жара схлынет — люди снова добрыми станут. Магнитные бури, слыхала? Ожидается всплеск насилия. Ты это, кажется, уже на своей шкурке почувствовала. Потерпи немного — Леший надует своих лягушек через задницу, и хлынет дождь."},{"kind":"paragraph","text":"— У нас всё через одно место, — смеётся Масяня."},{"kind":"paragraph","text":"— Ты смеёшься, красавица, — значит, не всё потеряно. Смех сквозь слёзы — это к дождю. Не унывай. Корней — сволочь, но он нам работу даёт."},{"kind":"paragraph","text":"— Ладно, мальчики, идите отдыхать. За мной заедут. А вас дома жёны ждут."},{"kind":"paragraph","text":"Побрели устало в раздевалку, по пути пересчитывая наличный заработок. И улыбались — широко и нагло. Давно так не улыбались."},{"kind":"paragraph","text":"Синева под глазом Масяни помогла получить честно заработанное. Несправедливость в одном отыгралась на правде в другом. В Машке вдруг проснулась училка: честное, светлое, униженное и оскорблённое существо — персонаж Достоевского. А всего-то нужно было приложить к нежному глазу красавицы кулак разгневанной законной супруги Корнея."},{"kind":"paragraph","text":"Почему так? Чтобы добиться правды, необходимо кого-то побить. Есть что-то ненастоящее в этой формуле. Несвободное. Какая-то праведность поневоле."},{"kind":"paragraph","text":"А завтра? Что будет завтра с Машенькой, когда обида на жену боцмана рассеется в обильных подарках бригадира? Снова проснётся бестия и урежет с нас часть заработка в пользу начальства? Так оно и будет. На том и держится поток."},{"kind":"paragraph","text":"Зачем очищать его искусственными наслоениями — шлюзами, порогами, фильтрами? В мутном потоке не видно подводное кладбище. Никто не придёт и не спросит. А Корней станет богаче и наглее. Жизнь — это и есть мутный поток. Слабые ручейки родниковых источников разбавляют тёмные воды, но не очищают. А кто они, эти слабые ручейки? Святые старушки, вымаливающие дождя, и Леший, надувающий лягушек через задницу — ради любви к человечеству. Только не мы с Лёвой."},{"kind":"paragraph","text":"В раздевалке собрали остатки недопитой водки, переоделись, сели за стол и выпили. Потом покурили и тронулись в путь. Я — в стареньких джинсах и футболке с надписью «Ч». Что означает, не знаю. Мне наплевать, лишь бы удобно было. А Лев надел белую рубашку и чёрные штаны — не даёт гравёру покоя высокородная армянская кровь. Что ж, его дело. Я проще. Неважно, как и во что одет, главное — сколько наличности в карманах."},{"kind":"paragraph","text":"Наш заработок — через «конверт». Боцман не для того бесплатные захоронения у высших устраивает, чтобы налоги платить. Корней — жук. Его бизнес подразумевает умение ладить с живыми, чтобы не обижать покойников. На том свете налоговой нет. А ритуальный цех — блокпост на границе с вечностью. Кто же решится его проверять из земных, если впереди небо? А у неба границ нет — там всё общее."},{"kind":"paragraph","text":"Кто возвращался домой после адского рабочего дня, тот понимает, что есть рай на земле. Говорить ни о чём не хочется, мышцы гудят, как высоковольтные провода, тело — в невесомости. Тронь нас — выскочит разряд молнии и сразит наповал. Мы идём спокойно и радостно, но наши лица как бы говорят окружающим: не прикасайтесь, высокое напряжение, убьёт. Не хватает лишь черепа с костями. Может быть, моя буква «Ч» на футболке — об этом?"},{"kind":"paragraph","text":"В воздухе разливается нега. Встречаются прохожие: гуляют влюблённые парочки, резвятся подростки, город пробуждается от жары. И когда люди спят? Ещё больше интересно — когда они работают? Иногда кажется, что в нашем городе летом люди вообще не работают, а только отдыхают."},{"kind":"paragraph","text":"Я хорошо отличаю лица живых от мёртвых. Вторые — в потоке, в котором мы с Лёвой проводники. «Живые» — лица чужие, не свои, они как будто только что из эдемского сада: веселятся, как ангелы, удивляются жизни, как дети, в них неистребимая жажда жить. Свои — лица из потока: серые, с погасшими глазами, усталые и разочарованные, циничные, непотребные, словно вырезанные из камня. Трезвые в опьянении и пьяные в трезвости. Наши лица. Свои."},{"kind":"paragraph","text":"Те, другие, — как апостолы в Пятидесятницу, когда на них снизошёл дух святой и они показались мёртвым «пьяными», — такой эффект зазеркалья."},{"kind":"paragraph","text":"Мне тоже иногда кажется: человек в радости — это ненормальный человек. Разве можно сегодня быть в радости? Радуются и веселятся сегодня святые — люди, не утратившие способность радоваться. О Господи, как я завидую этим детям Божьим! Хорошей завистью. Белой."},{"kind":"paragraph","text":"Недалеко от светлого сверкающего пятачка гостиницы — развилка. Лев идёт направо, я — налево. Мне добираться до Балтийского района, Лёва живёт в центре."},{"kind":"paragraph","text":"— До завтра, — протягивает руку приятель и смеётся. — Смотри, не сверни куда-нибудь. Тебя ждёт женщина — холодная, как пиво, и крепкая, как вино."},{"kind":"paragraph","text":"— Не сверну. Надеюсь, что завтра Леший надует своих лягушек. И хлынет дождь. Мозги плавятся."},{"kind":"paragraph","text":"Иду мимо церкви. Возле кованой изгороди курит охранник. Я его знаю: Костя с Ленинского, инвалид войны. У него время от времени мина в голове начинает тикать часовым механизмом — он становится замкнутым и неразговорчивым, берёт отгулы и ложится в стационар. Потом настоятель его снова принимает сторожем. Жалеет. Костю многие знают в городе: он свой повсюду. Не живой и не мёртвый — особенный какой-то. Дурачок. Типа Лешего. Такие — неопределимы. Они ближе к живым, чужим то есть, но одновременно в них много «своей» мёртвости."},{"kind":"paragraph","text":"Получил ранение в голову и контузию ещё во время Первой Чеченской. Прозвище у Кости — остаточный позывной: Череп. Теперь он вполне олицетворяет название: лысина с трагическим проёмом отливает синевой лунного света, борода сползает на грудь. Здороваюсь."},{"kind":"paragraph","text":"— Отработал? Замолвил бы за меня словечко перед своим боссом — я бы научился. На рынок звали в мясной отдел, отец Евгений не пускает. Говорит, что в мясном цехе мне нельзя: крови много, суеты, людей. Крыша поедет. А у вас как? Ничего?"},{"kind":"paragraph","text":"— У нас? — Смеюсь. — Крыша давно едет. Ты у отца Евгения спроси. Но, скорее всего, к нам он тебя не благословит. У нас без водки нельзя, а тебе нельзя с водкой."},{"kind":"paragraph","text":"— Почему без водки нельзя?"},{"kind":"paragraph","text":"— Без водки с ума сойдёшь быстрее. Нашему боссу нужен поток, понимаешь? А трезвый в потоке не может. Ему отдохнуть иногда хочется, и брак от усталости больше. Поток сам себя организовал. Невозможно быть трезвым в потоке. Теперь понял?"},{"kind":"paragraph","text":"— Теперь понял. Не дурак. Но ты всё-таки поимей в виду. Может быть, уволится кто, работник потребуется — словечко замолви. Тягостно тут в церкви. От безделья тягостно. Хоть бы враг какой пошёл. Я б его… я б его… — И по сторонам озирается, будто потерянный автомат ищет. — Я б его, блядь, сапёрной лопаткой в голову. Он мне в пяту как змий, а я его в голову. Один удар сапёрной лопаткой — и нет головы. Он мне в пяту, а я в голову, понимаешь, Серый? Змий мне в пяту, а я его…"},{"kind":"paragraph","text":"Заклинило Черепа на сапёрной лопатке и змии. Бывает."},{"kind":"paragraph","text":"— О, это я понимаю, Костя. А если он тебя в голову? Ты его в пяту?"},{"kind":"paragraph","text":"— Что? — Череп выходит из самогипноза. — Об этом я не подумал. — Качает головой в недоумении. — Спасибо, что подсказал. Теперь думать буду. Если он меня в голову… Эх, йофама, надо к отцу Евгению подойти и спросить. Что делать, если враг в голову, а не в пяту? Знаю, что скажет. У нас враг невидимый — духи злобы поднебесной. Так и говорит иногда в церкви на проповеди: у нас, говорит, у православных, главный враг — это мы сами. В нас самих сидит дух злобы поднебесной. С ним и надо воевать. Как это, Серый? Я сам себя должен в голову, что ли? Долбить? Эх, йофама…"},{"kind":"paragraph","text":"Сторож отшвырнул от себя окурок, как бикфордов шнур, заходил взад-вперёд в задумчивости, а я отправился дальше — в сторону огней проспекта и гостиничной суеты. На пятачок, где таксисты ждут клиентов, где бродят ночные граждане без «церковных затей» и заморочек, где много разных ручейков стекаются в единый ночной городской поток, в котором всем хорошо — особенно летом, в жаркие ночи. Как в Сочи."},{"kind":"paragraph","text":"Бабушки (не святые) торгуют цветами с дач, а под полами балахонов держат ключи от квартир — на ночь, за деньги и бутылки своей наливной. Знаю: делают это не корысти ради, как колдун Иванов. Бабушки — люди старой закалки. Они почти все — в потоке. Ждут лишь гласа, вопиющего с неба, готовятся заранее, без ропота, и копят деньги на похороны."},{"kind":"paragraph","text":"А ещё — скажу по секрету (узнал как-то от Кости): бабушки эти, не святые, собирают копеечку на вставные челюсти. Да, не вру. Хотят выглядеть в гробах невестами Христовыми, просят внуков обязательно надеть перед погребениями новые зубы и косы, хранимые с юности, сунуть под подушки в гробы. Когда явятся красавицами перед Христом, он и простит их — как дев евангельских, которые с сосудами масла и огоньками светильников вышли встречать Жениха. Не вру. Мне об этом церковный сторож рассказывал. А Череп не врёт. Не умеет."},{"kind":"paragraph","text":"Вдоль широкого мощёного тротуара растут липы. Время уже к полуночи, засиделись мы с Лёвой за остатками трапезы цеховой. Надо такси брать — и домой к Вике. Заждалась, красавица. Не то чтобы только меня, но меня с наличностью, которой сегодня чуть больше, чем всегда. Вот что может с человеком сделать синева под глазом. Думаю, наверное, поступок Машки сравним с надуванием лягушек Лешего — поступок святой. Потому как в один момент ветхая (в смысле — мёртвая) Масяня преобразовалась в раскаявшуюся грешницу: в училку без выкрутасов, в Марию Магдалину, в девушку, воскресшую из погребённых романов Фёдора Михайловича. Случилось чудо, надо признать. Завтра пойдёт дождь. Если не пойдёт — стану циничным и въедливым, как Фома неверующий."},{"kind":"paragraph","text":"Иду в сторону лип, под которыми что-то происходит. Возня какая-то, шум, плач едва ли не детский. Что-то там происходит нехорошее, я примерно предполагаю что. И обычно в чужие мутные ручейки не забираюсь, тем более не ныряю с головой — своего потока мутного хватает. Но тут что-то внутри меня ёрзает, покоя не даёт. Видно, проснулся внутри какой-то дух, который вышел на поле борьбы Бога и дьявола, за сердце схватил. А внутренний голос шепчет: «Пойди и дай кому-нибудь в морду, если увидишь несправедливость. Сотвори подвиг — такой же высокий, как сегодня Машка сотворила. И ещё не успел Лягушатник, которому воздастся от людей за любовь к людям: побьют Лешего за лягушек, а он просто преисполнился всеобщей любви. Пойди и дай скверному человеку в морду, душу отведи и разряд накопленных в жару молний низвергни на землю»."},{"kind":"paragraph","text":"Долго не противился внутреннему голосу и пошёл под липы. А там сутенёр издевается над подопечной. В белой рубашке тягает за волосы ночную фею, которой от силы лет восемнадцать. Она тоже вся в белом — в платьице с кружевами, похожем на школьное выпускное. Как видно, в образе работает. Знаю: проститутки тут почти все на веществах сидят, есть и те, кто нехорошими болезнями болеет."},{"kind":"paragraph","text":"— Ах ты, шалава! — кричит хозяин девушки. — Гонорар взяла — всё по столице Австрии (вене) пустила. В хламину перед уважаемыми клиентами явилась! А работать? Кто за тебя гостей города обслуживать будет?!"},{"kind":"paragraph","text":"И снова — хрясь её по лицу. Не сильно, ладошкой — чтобы товарный вид не испортить, но больно и стыдно. Вижу: плохо совсем девочке. Тошнит её — то ли от передозировки, то ли от болезни. Никакая совсем."},{"kind":"paragraph","text":"Я, может быть, в другую минуту не стал вмешиваться и нырять в чужой мутный поток. Но сегодня на моих глазах произошло преображение Машки. И сам я, признаться, истосковался по обычной сваре — чтобы скопившуюся мерзость запустения душевного из себя изгнать. Надо заступиться. Иначе молнии внутренние меня самого испепелят."},{"kind":"paragraph","text":"— Земляк, оставь девушку. Не видишь, ей плохо? Какая она жрица любви — ей самой лекарь нужен. Оставь её, зёма. Она тебе здоровая бухгалтерию сделает. А сегодня — оставь."},{"kind":"paragraph","text":"Наискосок от меня стоят на тротуаре два парня в камуфляже. Худые, крепкие, прокопчённые. С мёртвыми лицами — своих внутри потока узнаю с первого взгляда. Шевроны чёрные с белыми черепами — вот она, буква «Ч». От них на расстоянии ощущается предупреждение: не встревай — убьём. Это клиенты. Им нужна ночная фея в образе школьницы. У них много денег и совсем нет страха. Наверное, гонорар они дали наперёд, а «школьница» их кинула, уехала с деньгами, промотала. Они вызвонили хозяина — и теперь тот вразумляет под липами «проколовшуюся» девицу."},{"kind":"paragraph","text":"— Ты кто? — поворачивается ко мне сутенёр. Лицо тоже мёртвое — в потоке. Вроде не старый, а ведёт себя нагло. Косится на клиентов, подмигивает им. Он не боится меня. В трёх метрах стоят защитники — два камуфляжных бойца. Курят папиросы, от которых идёт кочегарный чад с примесью травки. Глаза сверкают. Кажется, они готовы разрядить свои молнии прямо сейчас под липами."},{"kind":"paragraph","text":"Я не унимаюсь. Я уже нырнул в чужой поток. Теперь остаётся либо утонуть, либо выплыть. Третьего не дано. А силы в моём теле по-прежнему кипят — хотят благородного выхлопа."},{"kind":"paragraph","text":"«Дайте мне точку опоры, и я переверну землю». Мне точка опоры не нужна. Я уже начал переворачивать землю."},{"kind":"paragraph","text":"— Я смерть твоя, вот кто я. Всадник Апокалипсиса. Оставь девицу. А ты, детка, встань и иди. Я разговаривать с твоим псом буду."},{"kind":"paragraph","text":"Белое платье девушки неожиданно растворилось в ночи. Ночная фея упорхнула, предчувствуя неладное."},{"kind":"paragraph","text":"Рефлекторно я затянул молнию на карманах джинсов, где лежала наличность, и шагнул в сторону наглеца. Схватил его за шиворот белой рубахи. Силы не рассчитал — воротник треснул, сутенёр побледнел, стал звать на помощь. Но я не дал ему разогнаться в потоке — притянул за штаны и отвесил крепкую оплеуху. И согрешил — оставил камуфляжных без внимания."},{"kind":"paragraph","text":"Они подошли ко мне сзади бесшумно, как кошки. Наверное, решили снять вражеского часового с поста. И ударили. Сзади. По голове. По затылку. Как Череп хотел — в голову, а не в пяту."},{"kind":"paragraph","text":"О, эти «гравёры» крепко держали в руках кувалду. Били по скарпелю прицельно и дерзко. Вышибали в мозгах моих: «Не любим. Не помним. Скорбеть не будем». У них свой юморок — с червоточинкой. Били так, что в какой-то момент я отчётливо услышал церковный колокол. И увидел сквозь муть потока стайку тёмных старух и Лешего, надувающего лягушек. Кричать я не мог. Лежал под липами и глотал воздух, словно рыба, выброшенная на берег."},{"kind":"paragraph","text":"«Лёва, я тебя умоляю, не нужно пошлых розочек и сериальной скорби. Напиши бодрящее: \"Он шёл по жизни, чуть шатаясь\". Не надо скорбеть и помнить»."},{"kind":"paragraph","text":"Кажется, я надул через задницу огромную жабу и запустил её прямо в небеса. Авось откликнутся."},{"kind":"paragraph","text":"Вика, Лёва, Игнат, Машка, Леший, Череп, Корней, старушки с косами и новыми зубами."},{"kind":"paragraph","text":"Господи, как хорошо…"},{"kind":"paragraph","text":"Очнулся под липами под утро — от странного шелеста сверху. Будто ангелы крыльями зашуршали в кронах деревьев. И по лицу — нежно и ласково — заплясали…"},{"kind":"paragraph","text":"Боже, это же дождь!"},{"kind":"paragraph","text":"Случилось чудо."},{"kind":"paragraph","text":"Скарпели камуфляжных пробили небеса и влезли в потусторонние нейронные связи."},{"kind":"paragraph","text":"И хлынул дождь."},{"kind":"paragraph","text":"Долгожданный, чудесный, преображающий."},{"kind":"paragraph","text":"Нет, я не плакал. Не имею такой привычки."},{"kind":"paragraph","text":"Это был дождь."}]'::jsonb,
  '2026-01-20T12:00:00.000Z'
)
