INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd6-derevo',
  'Дерево',
  (SELECT id FROM "Authors" WHERE name = 'Роман Щепец' ORDER BY id LIMIT 1),
  'mrd6/mrd6-derevo.jpg',
  'data:image/jpeg;base64,',
  1381,
  797,
  'Зато есть время всё обдумать, никуда не торопясь, Моя шея рвётся в небо, мои корни уходят в грязь. Ну куда вы спешите, глупые? Я просто торчу из трав, Я дерево, дерево, дерево — ни обязанностей, ни прав.',
  '[{"kind":"image","path":"mrd6/mrd6-derevo.jpg","caption":null},{"kind":"paragraph","text":"Зато есть время всё обдумать, никуда не торопясь, Моя шея рвётся в небо, мои корни уходят в грязь. Ну куда вы спешите, глупые? Я просто торчу из трав, Я дерево, дерево, дерево — ни обязанностей, ни прав."},{"kind":"paragraph","text":"«Дерево», Дайте танк (!)"},{"kind":"paragraph","text":"На голове и руках шуршит сухая листва, тело в онемении застыло, вросло глубоко в землю. Я — дерево. Вокруг скачут маленькие дети. Все веселятся, хороводят, готовятся к большому празднику. У каждого по игрушке, в основном плюшевой: мишки, зайчики, волчата… Звонкий детский смех скрипит стержнем сухого фломастера."},{"kind":"paragraph","text":"Из корпуса детского сада выходит воспитательница, и настроение детей резко меняется: лица их становятся серьёзнее, все выстраиваются в колонну по одному возле меня и внимательно слушают. Она раздаёт каждому ребёнку по паре рукавиц, солнцезащитные очки и фартук. Прошла в начало колонны, достала из передника разделочный нож. Ай! Нож прошёл через сухую кору и остался в стволе."},{"kind":"paragraph","text":"— Ребята, — выдёргивает и ещё раз с силой вгоняет между ребристых волокон, — каждый из вас по очереди должен сделать так же. Не забудьте оставить мягкого друга, бедняге не будет так одиноко. А теперь достаём колючки и-и-и-и-и-и, — протяжным стоном, с усилием дёргая за рукоять, — начали!"},{"kind":"paragraph","text":"По мне расползаются мелкие порезы, царапины, вмятины, ничего не могу поделать: корни глубоко в земле. Ширк-ширк-ширк! Из-под коры струится смола. Мальчик, только что ткнувший в меня шилом, хватается за низкую ветку и с силой дёргает её на себя. Скр-р-р-п. Листья падают на землю. Из места, где переломилась ветка, начинает течь кровь. Шурх."},{"kind":"paragraph","text":"— Ты что такое делаешь? Кто разрешал висеть на ветвях? Это тебе не качели. А ну, быстро слезь! — воспитательница дёрнулась с места и стащила мальчика на землю. — Дети, не трогайте ветки и листья! Они ядовиты, они пусты, в них нет жизни!"},{"kind":"paragraph","text":"Когда в меня робко вонзилась последняя иголочка, у корней выстроилась уже целая армия старых игрушек. Детские крики куда-то пропали. У-у-у-у. Налетел сильный ветер, игрушки зашевелились. Они стали плотно цепляться друг за друга, образуя плюшевый ураган, мягкий хороводоворот."},{"kind":"paragraph","text":"Мишки, зайчики, волчата, лисички, слоники, щенята и прочие, прочие звери, пыльные и грязные, вырваны глаза и обгрызены уши, забесновались в каком-то диком прерывистом танце, всё время сужая круг и подступая всё ближе к стволу, пока окончательно не прижались, образовав тесную цепь."},{"kind":"paragraph","text":"Ветер вскоре стих, вокруг снова засуетилась малышня. В этот раз вместе с воспитательницей вышел ещё один человек — дворник. В руках у него не было ни метлы, ни совка, ни даже ножниц. Он тащил большую канистру."},{"kind":"paragraph","text":"— Дети, отойдите подальше и наденьте очки, — скомандовала воспитательница."},{"kind":"paragraph","text":"Дворник принялся выливать содержимое канистры на ствол и ветки. Горючее вещество соприкасалось со смолой, образуя ужасный едкий запах. Залил землю и игрушки. Тёмно-жёлтые, как я. Бензин питает корни, крону кружит, кренит."},{"kind":"paragraph","text":"Чиркнула спичка. Высокая огненная стена выстроилась. Сменяющие друг друга одинаково поющие детские лица спрятались под очками. Раны коптятся. Закручиваются в сплошной треск-хруст. Ш-ш-ш."},{"kind":"paragraph","text":"Рассказ победителя пятого сезона конкурса рок-прозы «Гроза»."}]'::jsonb,
  '2026-01-20T12:00:00.000Z'
)
